/* LA SESIÓN EN CURSO SE GUARDA. Antes vivía solo en memoria: cerrar la app a mitad de entreno la
   perdía. Ahora ui.gymSesionActiva lee y escribe store.gym.activa, así que todo el código que ya la
   usaba sigue igual y la sesión sobrevive a recargar (y el cierre automático la termina si se olvida). */
Object.defineProperty(ui,'gymSesionActiva',{enumerable:true,configurable:true,
  get:function(){return (store&&store.gym&&store.gym.activa&&typeof store.gym.activa==='object')?store.gym.activa:null;},
  set:function(v){if(!store)return;gymS().activa=v||null;}});
function load(){
  let ok=false,raw=null,habiaAlgo=false;
  try{raw=localStorage.getItem(KEY);
    habiaAlgo=!!(raw&&raw!=='undefined'&&raw!=='null');
    if(habiaAlgo){const o=JSON.parse(raw);
      if(o&&Array.isArray(o.shifts)&&o.menu&&Array.isArray(o.dishes)){store=o;ok=true;}}}catch(e){
    console.warn('no se pudo leer el planning guardado, se arranca de cero');}
  if(!ok){store=DEFAULTS();
    /* LO QUE NO SE PUEDE LEER SE APARTA ANTES DE NADA. Antes el mensaje prometía «no hemos borrado
       nada» y el primer pintado guardaba el ejemplo encima. Ahora se copia tal cual a otra clave (la
       primera vez: un segundo fallo no pisa el rescate bueno) y, si ni eso se puede, no se guarda nada
       hasta que importes o restaures a mano. */
    if(habiaAlgo){let apartado=false;
      try{if(!localStorage.getItem(RKEY))localStorage.setItem(RKEY,raw);apartado=true;}catch(e){}
      if(!apartado)_noPisar=true;
      setTimeout(function(){flash('⚠ no se ha podido leer tu planning guardado (datos dañados o de un formato antiguo): se ha cargado el ejemplo. '+
        (apartado?'Lo que había está apartado: en Datos → Copias puedes copiarlo':'No se guardará nada encima hasta que importes una copia'),9000);},0);}}
  normalize(store);
  /* primer arranque: no hab\u00eda NADA guardado y no viene de una copia ya montada. Quien ya tiene
     sus datos no ve el asistente nunca, ni aunque actualice la app. */
  if(!habiaAlgo&&!(store.meta&&store.meta.montada))ui.arranque={paso:0,jEntra:'08:00',jSale:'15:00',
    gEntra:'08:00',gSale:'08:00',gMes:4,despierta:'06:50',acuesta:'22:40',sitio:SITIOS_FIJOS[0].id};
  try{const m=JSON.parse(localStorage.getItem(MKEY)||'[]');if(Array.isArray(m))ui.marks=new Set(m);}catch(e){}
  try{if(localStorage.getItem(TKEY)!=='light')document.documentElement.classList.add('dark');}catch(e){document.documentElement.classList.add('dark');}
  aplicarTema();aplicarColoresCal();
}
