    v:{bg:'#eef2f9',bg2:'#e6ecf7',card:'#ffffff',ink:'#0d1729',ink2:'#5a6d8a',line:'#dbe4f2',brand:'#2563eb',brand2:'#7c3aed',accent:'#15803d'},
