let saveFailWarned=false,_escritoTxt='';
function save(){
  /* lo guardado cambia los datos: las memorias «por pintado» (¿vengo de guardia?, la semana de
     entrenos, la cocina…) ya no valen. Sin esto, poner una guardia y exportar sin repintar mandaba
     el saliente del día siguiente con el dato viejo —o no lo mandaba— */
  if(!_pintando)_renderTick++;
  /* los índices de comida (alimentos, buscables, la frase) se rehacen solo si los datos han cambiado
     DE VERDAD: muchos pintados guardan sin tocar nada, y cada uno tiraba el índice */
  let txt='';try{txt=JSON.stringify(store);}catch(e0){}
  if(!txt||txt!==_ultimoTxt){_datosV++;_ultimoTxt=txt;}
  /* save() va en cada tecla y casi siempre con los mismos datos: lo ya escrito no se vuelve a escribir */
  if(!_noPisar&&(!txt||txt!==_escritoTxt))try{localStorage.setItem(KEY,txt||JSON.stringify(store));_escritoTxt=txt;saveFailWarned=false;}catch(e){_escritoTxt='';console.warn('no se pudo guardar',e);
  if(!saveFailWarned){saveFailWarned=true;flash('⚠ no se ha podido guardar: el navegador no deja escribir (¿modo incógnito o memoria llena?). Copia tu JSON desde «Datos» antes de cerrar esta pestaña',6000);}}
  /* y si tienes el calendario enchufado, que se suba solo. No aquí mismo: save() se llama en cada
     tecla y subir cuatro ficheros en cada una sería absurdo. Se pide, y el temporizador decide. */
  try{calSyncPide();}catch(e){}}
function saveMarks(){try{localStorage.setItem(MKEY,JSON.stringify(Array.from(ui.marks)));}catch(e){}}
const shiftById=id=>store.shifts.find(s=>s.id===id);
const shiftByCode=c=>store.shifts.find(s=>s.code===c)||(c&&store.shifts.find(s=>s.name.toLowerCase()===String(c).toLowerCase()));
const dishById=id=>store.dishes.find(d=>d.id===id);
const mealById=id=>store.meals.find(m=>m.id===id);
const batchById=id=>store.batches.find(b=>b.id===id);
const isBatch=id=>!!id&&id!=='bn';

function rotationStrip(){
  /* el ciclo de semanas tipo, con lo que exige de cocina cada una */
  if(!store.patterns.length)return '';
  const rows=store.patterns.map(function(p,i){
    const codes=p.days.map(function(c){return resolveCode(c)||'';});
    const g=codes.filter(function(id){return isGuardia(shiftById(id));}).length;
    const plan=planBatches(codes.map(function(id){return {shiftId:id||null};}));
    const keys=Object.keys(plan).filter(function(k){return plan[k].hasNeed;});
    const rac=Math.round(keys.reduce(function(a,k){return a+plan[k].portions;},0)*10)/10;
    const dots=codes.map(function(id){const sh=shiftById(id);
      return `<span class="tag" style="background:${sh?sh.color+'22':'transparent'};color:${sh?sh.color:'var(--ink2)'};padding:2px 6px" title="${sh?esc(sh.name):'sin asignar'}">${sh?esc(sh.icon):'·'}</span>`;}).join('');
    return `<tr><td><b>${i+1}</b></td><td>${esc(p.name)}</td><td>${dots}</td><td><b>${g}</b></td><td>${rac} rac. · ${keys.length} sesión(es)</td></tr>`;
  }).join('');
  const active=store.patterns[store.rotation.pattern];
  return `<div style="margin-top:12px"><b class="mini">CICLO DE SEMANAS · se repite en este orden${store.rotation.mode==='date'?' y está anclado al '+esc(store.rotation.anchor||'')+' como lunes de la semana 1':''}</b>
    <table style="margin-top:4px"><thead><tr><th>#</th><th>Semana tipo</th><th>L→D</th><th>G</th><th>Cocina que exige</th></tr></thead><tbody>${rows}</tbody></table>
    <p class="mini" style="margin-top:6px">Semana en pantalla: <b>${active?esc(active.name):'—'}</b>. En modo fecha la app elige la fila que toca según el calendario; en modo plantilla la eliges tú.</p></div>`;
}

/* ===================== semana ===================== */
let weekDate=mondayOf(new Date());
let _renderTick=0,_pintando=false,_datosV=0,_ultimoTxt='';   /* _pintando: dentro de un pintado, guardar no tira lo memorizado */
let _weekDaysCache=null,_weekDaysTick=-1;
function weekDays(){
  if(_weekDaysTick===_renderTick&&_weekDaysCache)return _weekDaysCache;
  const r=store.rotation,out=[];
  if(r.mode==='date'){
    for(let i=0;i<7;i++){
      const d=addDays(mondayOf(weekDate),i);
      const inf=dayInfo(iso(d));
      const legacy=(r.shiftByDay&&r.shiftByDay[iso(d)]!==undefined)?r.shiftByDay[iso(d)]:null;
      const shiftId=inf.shiftId||(typeof legacy==='string'?legacy:null);
      out.push({date:d,key:iso(d),label:DAYN[i],short:DAYSH[i],sub:d.getDate()+' '+MON[d.getMonth()],
        shiftId:shiftId,auto:inf.auto&&!legacy,guard:inf.guard,pat:inf.pat,day:inf.day,inf:inf});
    }
  }else{
    const p=store.patterns[r.pattern]||store.patterns[0]||{days:[]};
    for(let i=0;i<7;i++){
      const manual=(r.shiftByDay&&r.shiftByDay['tpl'+r.pattern+'#'+i]!==undefined)?r.shiftByDay['tpl'+r.pattern+'#'+i]:null;
      out.push({date:null,key:null,label:DAYN[i],short:DAYSH[i],sub:'',
        shiftId:(typeof manual==='string'?manual:null)||resolveCode(p.days[i]),auto:manual==null,idx:i,guard:''});
    }
  }
  _weekDaysCache=out;_weekDaysTick=_renderTick;
  return out;
}
function shiftForDate(date){
  const r=store.rotation;
  if(!r.anchor||!store.patterns.length)return null;
  const a=parseDate(r.anchor);if(!a)return null;
  const src=(typeof date==='string')?parseDate(date):date;if(!src)return null;
  const d=new Date(src.getTime());d.setHours(12,0,0,0);
  const a12=new Date(a.getTime());a12.setHours(12,0,0,0);
  const idx=Math.round((Date.UTC(d.getFullYear(),d.getMonth(),d.getDate())
                        -Date.UTC(a12.getFullYear(),a12.getMonth(),a12.getDate()))/86400000);
  const cycle=store.patterns.length*7;
  const pos=((idx%cycle)+cycle)%cycle;
  const p=store.patterns[Math.floor(pos/7)];
  const day=pos%7;
  const raw=r.index!==undefined&&p.days[day]!==undefined?p.days[day]:null;
  return {shiftId:resolveCode(raw),pat:Math.floor(pos/7),day:day,pattern:p};
}
function resolveCode(c){
  if(!c)return null;
  if(store.shifts.some(s=>s.id===c))return c;
  const s=shiftByCode(c);
  return s?s.id:null;
}
/* ===================== notas =====================
   Una nota es un trozo de texto que puede tener día o no tenerlo. Sin día vive solo en la libreta y
   no ensucia el calendario; con día sale en la casilla del Mes y al abrirlo. Si además la pasas al
   calendario, la nota guarda el id del evento (evId): no se duplica nada, se enlaza. */
const NOTA_PURGA_DIAS=2;
function notasS(){
  if(!Array.isArray(store.notas))store.notas=[];
  return store.notas;}
function migraNotasDia(o){
  /* lo que ya tenías en store.notasDia era UNA nota por día, texto suelto. Pasa a la lista sin
     perder nada y sin crear duplicados si la migración ya se hizo. */
  const S=o||store;
  const viejo=S.notasDia;
  if(!viejo||typeof viejo!=='object')return 0;
  const ks=Object.keys(viejo);
  if(!ks.length)return 0;
  if(!Array.isArray(S.notas))S.notas=[];
  const lista=S.notas;
  let n=0;
  ks.forEach(function(k){
    const txt=String(viejo[k]||'').trim();
    if(!txt)return;
    if(lista.some(function(x){return x.fecha===k&&x.txt===txt;}))return;
    lista.push({id:uid('nt'),txt:txt,fecha:k,hecha:0,color:'',evId:'',ts:Date.now()});
    n++;});
  S.notasDia={};   /* ya vive en store.notas: dejarlo duplicado acabaría en dos verdades */
  if(n){olvidaNotas();if(S===store)save();}
  return n;}
function purgaNotas(o){
  /* «que se borre a los 2 días»: una nota marcada como hecha se queda a la vista dos días —por si te
     arrepientes— y luego se va sola. Se mira al cargar el almacén y al entrar en Notas. */
  const S=o||store;
  if(!Array.isArray(S.notas))S.notas=[];
  const lista=S.notas,limite=Date.now()-NOTA_PURGA_DIAS*86400000;
  let n=0;
  for(let i=lista.length-1;i>=0;i--){
    const x=lista[i];
    if(x.hecha&&x.hecha<limite){lista.splice(i,1);n++;}}
  if(n){olvidaNotas();if(S===store)save();}
  return n;}
function notaById(id){return notasS().filter(function(x){return x.id===id;})[0]||null;}
let _notasIdx=null,_notasTick=-1;
function olvidaNotas(){_notasIdx=null;_notasTick=-1;}
function notasPorFecha(){
  /* La cuadrícula del mes preguntaba por las notas de cada una de sus 31 casillas, y cada pregunta
     barría la lista entera y la ordenaba: 31·N. Un índice por pintado lo deja en 1·N. Se rehace
     cuando cambia el pintado, igual que hace monthDays(). */
  if(_notasTick!==_renderTick||!_notasIdx){
    _notasIdx={};
    notasS().forEach(function(x){
      if(!x.fecha)return;
      (_notasIdx[x.fecha]||(_notasIdx[x.fecha]=[])).push(x);});
    Object.keys(_notasIdx).forEach(function(k){
      _notasIdx[k].sort(function(a,b){return (a.hecha?1:0)-(b.hecha?1:0)||a.ts-b.ts;});});
    _notasTick=_renderTick;}
  return _notasIdx;}
function notasDeFecha(key){return notasPorFecha()[key]||[];}
function notasAviso(key){
  /* «si pongo una nota en un día, que se sobreentienda que es importante»: una nota CON DÍA y sin
     hacer es un aviso de ese día, y sale en Mes, Semana y Hoy como los eventos. La que ya se pasó a
     evento no se repite (sale el evento); la que no tiene día se queda en la libreta y no molesta. */
  return notasDeFecha(key).filter(function(x){return !x.hecha&&!notaCubierta(x);});}
function notaCubierta(x){return !!(x.evId&&eventoDeNota(x));}   /* pasada a evento y el evento sigue: sale el evento, no ella */
function notaDia(key){
  /* se queda por compatibilidad: las notas de un día, en una sola cadena */
  return notasDeFecha(key).map(function(x){return x.txt;}).join('\n');}
function addNota(txt,fecha){
  const t=String(txt||'').trim().slice(0,600);
  if(!t)return {ok:false,msg:'escribe algo primero'};
  const f=fecha?(foodKey(fecha)||''):'';
  const nota={id:uid('nt'),txt:t,fecha:f,hecha:0,color:'',evId:'',proy:'',ts:Date.now()};
  notasS().push(nota);olvidaNotas();save();
  return {ok:true,id:nota.id,msg:'apuntado'+(f?(' para el '+fechaCorta(f)):'')};}
function setNota(id,campo,valor){
  const x=notaById(id);if(!x)return 'esa nota ya no está';
  if(campo==='txt')x.txt=String(valor||'').slice(0,600);
  else if(campo==='fecha'){const nf=valor?(foodKey(valor)||''):'';
    /* nota y evento son una sola cosa: si la nota está en el calendario, su evento se mueve con ella
       (antes se quedaba en la fecha vieja), y no se puede quedar sin día mientras lo esté */
    if(x.evId){const ev=evById(x.evId);
      if(ev&&!nf)return 'primero quítala del calendario: su evento tiene fecha';
      if(ev&&ev.modo==='fecha')ev.fecha=nf;}
    x.fecha=nf;}
  else if(campo==='color')x.color=esColor(valor||'')?valor:'';
  else if(campo==='proy')x.proy=String(valor||'').trim().slice(0,40);
  olvidaNotas();save();return '';}
function proyectos(){
  /* los proyectos no se crean en ningún sitio: son el nombre que le pones a una nota, y la lista
     sale de las que ya tienes. Una cosa menos que administrar. */
  const c={};
  notasS().forEach(function(x){const p=(x.proy||'').trim();if(!p)return;
    if(!c[p])c[p]={nombre:p,total:0,pend:0};
    c[p].total++;if(!x.hecha)c[p].pend++;});
  return Object.keys(c).map(function(k){return c[k];})
    .sort(function(a,b){return b.pend-a.pend||a.nombre.localeCompare(b.nombre,'es');});}
function notasDeHoy(){
  /* lo que toca hoy y lo que se te pasó: es lo que convierte la libreta en una lista de tareas */
  const hoy=iso(new Date());
  const pend=notasS().filter(function(x){return !x.hecha&&x.fecha;});
  return {hoy:pend.filter(function(x){return x.fecha===hoy;}),
    tarde:pend.filter(function(x){return x.fecha<hoy;})
      .sort(function(a,b){return a.fecha.localeCompare(b.fecha);})};}
function notasDeLaSemana(){
  const hoy=new Date(),ini=iso(hoy),fin=iso(addDays(hoy,7));
  return notasS().filter(function(x){return !x.hecha&&x.fecha&&x.fecha>=ini&&x.fecha<=fin;});}
function toggleNotaHecha(id){
  const x=notaById(id);if(!x)return 'esa nota ya no está';
  x.hecha=x.hecha?0:Date.now();olvidaNotas();save();
  return x.hecha?('hecha · se borra sola dentro de '+NOTA_PURGA_DIAS+' días'):'vuelve a estar pendiente';}
function delNota(id){
  const lista=notasS(),i=lista.findIndex(function(x){return x.id===id;});
  if(i<0)return 'esa nota ya no estaba';
  lista.splice(i,1);olvidaNotas();save();return 'nota borrada';}
function notaAEvento(id,opts){
  /* de nota a evento del calendario. La nota NO se copia: se queda enlazada por evId, así que si
     cambias la hora en un sitio es la misma en el otro. */
  const x=notaById(id);if(!x)return {ok:false,msg:'esa nota ya no está'};
  opts=opts||{};
  const fecha=foodKey(opts.fecha||x.fecha||'');
  if(!fecha)return {ok:false,msg:'ponle primero un día a la nota'};
  const titulo=String(opts.titulo||x.txt.split('\n')[0]||'').trim().slice(0,60);
  if(!titulo)return {ok:false,msg:'la nota está vacía: no sé cómo llamar al evento'};
  const ev={id:uid('ev'),titulo:titulo,modo:'fecha',fecha:fecha,
    hora:String(opts.hora||'').slice(0,5),fin:String(opts.fin||'').slice(0,5),
    color:x.color||tlColor('evt'),on:true,
    recordatorio:!!opts.recordatorio,cuentaAtras:!!opts.cuentaAtras,notaId:x.id};
  eventosS().push(ev);
  x.fecha=fecha;x.evId=ev.id;olvidaNotas();save();
  return {ok:true,ev:ev,msg:'en el calendario: '+titulo+' · '+fechaCorta(fecha)};}
function desenlazaNota(id){
  const x=notaById(id);if(!x)return 'esa nota ya no está';
  if(!x.evId)return 'esta nota no tiene evento';
  const evs=eventosS(),i=evs.findIndex(function(e){return e.id===x.evId;});
  if(i>=0)evs.splice(i,1);
  x.evId='';save();
  return 'fuera del calendario · la nota se queda con su día';}
function eventoDeNota(x){
  if(!x||!x.evId)return null;
  return eventosS().filter(function(e){return e.id===x.evId;})[0]||null;}
function notasCuenta(){
  const c={total:0,sinDia:0,conDia:0,hechas:0,hoy:0,tarde:0,semana:0};
  const hoy=iso(new Date()),fin=iso(addDays(new Date(),7));
  notasS().forEach(function(x){c.total++;
    if(x.hecha){c.hechas++;return;}
    if(x.fecha){c.conDia++;
      if(x.fecha===hoy)c.hoy++;
      else if(x.fecha<hoy)c.tarde++;
      if(x.fecha>=hoy&&x.fecha<=fin)c.semana++;}
    else c.sinDia++;});
  return c;}
function dayOverride(dateStr){const v=(store.rotation.daySet||{})[dateStr];if(v===undefined||v===null||v==='')return null;
  return (typeof v==='string')?{shift:v,guard:''}:{shift:v.shift||'',guard:v.guard||''};}
function setDayOverride(dateStr,shiftId,guard){
  if(!_pintando)_renderTick++;   /* cambia el tipo de un día: lo memorizado ya no vale */
  if(!store.rotation.daySet)store.rotation.daySet={};
  if(shiftId===null){delete store.rotation.daySet[dateStr];limpiarSalientesAuto(dateStr);return {pos:null};}
  store.rotation.daySet[dateStr]=(guard&&shiftId)?{shift:shiftId,guard:guard}:{shift:shiftId||''};
  /* devuelve lo que hizo con el día siguiente: quien llama ya no vuelve a decidirlo por su cuenta */
  const sh=shiftById(shiftId);let pos=null;
  if(sh&&isGuardia(sh)){if(store.rotation.autoPos!==false)pos=ponerSalienteAuto(dateStr);}
  else limpiarSalientesAuto(dateStr);
  return {pos:pos};}
function saltoDia(){const s=(store.rotation&&store.rotation.saltoDia)||{};
  const from=(s.from!=null?+s.from:6),to=(s.to!=null?+s.to:1);
  return {from:isNaN(from)?6:from,to:isNaN(to)?1:to};}
function saltoDiaTxt(){const s=saltoDia();return 'si cae en '+DOWN0[s.from]+', el '+DOWN0[s.to];}
function marcarAuto(fecha,shiftId,de){
  if(!shiftId)return false;
  const cur=dayOverride(fecha);
  if(cur&&!cur.auto)return false;              /* si ya lo pusiste tú a mano, no te lo toco */
  if(cur&&cur.auto&&cur.auto!=='pos')return false;
  if(vacationOf(fecha))return false;           /* en vacaciones no se escribe nada */
  store.rotation.daySet[fecha]={shift:shiftId,auto:'pos',de:de};return true;
}
function ponerSalienteAuto(dateStr){
  /* la guardia se acaba a las 8 del día siguiente: ese día es saliente; si cae en el día que marque
     «Ajustes → qué día de la semana absorbe el saliente» (sábado→lunes de fábrica), los días de por
     medio quedan libres y el saliente se pasa al día configurado (se descansa en casa) */
  const S=shiftByCode('S'),L=shiftByCode('L'),d=parseDate(dateStr);
  if(!d)return {ok:false,msg:'fecha rara'};
  limpiarSalientesAuto(dateStr);
  const DN3=['Dom','Lun','Mar','Mié','Jue','Vie','Sáb'];const wd=d.getDay();let n=0,txt='';
  const sd=saltoDia();
  if(wd===sd.from){
    let gap=(sd.to-wd+7)%7;if(gap===0)gap=7;
    for(let i=1;i<gap;i++){const k=iso(addDays(d,i));if(L&&marcarAuto(k,L.id,dateStr))n++;}
    const destino=iso(addDays(d,gap));
    if(S&&marcarAuto(destino,S.id,dateStr)){n++;txt=' ('+DN3[wd]+' → el saliente cae el '+DN3[(wd+gap)%7]+')';}
  }else{
    const sig=iso(addDays(d,1));
    if(S&&marcarAuto(sig,S.id,dateStr)){n++;const dd=parseDate(sig);txt=' al '+DN3[dd.getDay()]+' '+dd.getDate();}
  }
  return {ok:n>0,txt:txt,n:n};}
function limpiarSalientesAuto(dateStr){
  const ds=store.rotation.daySet||{};
  Object.keys(ds).forEach(function(k){const v=ds[k];
    if(v&&typeof v==='object'&&v.auto==='pos'&&v.de===dateStr)delete ds[k];});}
function rhythmOf(shiftId,dateStr){
  const base=(store.rhythm&&store.rhythm[shiftId])||{};
  const ov=dateStr?((store.rotation.dayRhythm||{})[dateStr]||{}):{};
  const r={};Object.keys(base).forEach(k=>r[k]=base[k]);
  Object.keys(ov).forEach(k=>{if(ov[k]!==''&&ov[k]!=null)r[k]=ov[k];});
  return r;}
let _vacMapCache=null,_vacMapSig='';
function vacMap(){
  /* los rangos de vacaciones se traducen a días sueltos: así el calendario, la cocina y la compra los ven.
     dayInfo() llama a esto para CADA día que se pinta, así que se cachea por firma: reconstruir day-por-día
     un mapa entero en cada consulta era el cuello de botella medido en el informe de rendimiento (la pestaña
     Mes tardaba ~550ms con años de datos porque este mapa se rehacía cientos de veces por render). */
  const vs=(store.rotation&&store.rotation.vacaciones)||[];
  const n=store.shifts.filter(function(x){return /vacacion|festiv/i.test(String(x.name||''));})[0]||
    store.shifts.filter(function(x){return x.code==='V';})[0]||shiftById('sh-v');
  const sig=(n?n.id:'')+'|'+vs.length+'|'+vs.map(function(v){return v.start+'~'+v.end+'~'+(v.label||'');}).join(',');
  if(_vacMapCache&&_vacMapSig===sig)return _vacMapCache;
  const out={};
  if(!n){_vacMapCache=out;_vacMapSig=sig;return out;}   /* sin tipo de día de vacaciones no hay mapa, pero tampoco vacío: esto se llamaba así y reventaba */
  vs.forEach(function(v,ix){const a=parseDate(v.start),b=parseDate(v.end);if(!a||!b)return;
    const lo=a<=b?a:b,hi=a<=b?b:a;
    for(let d=new Date(lo.getTime());d<=hi;d=addDays(d,1)){const k=iso(d);
      if(!out[k])out[k]={shiftId:n.id,ix:ix,label:v.label||'vacaciones'};}});
  _vacMapCache=out;_vacMapSig=sig;
  return out;}
function vacationOf(dateStr){const v=vacMap()[dateStr];if(!v)return null;const vs=(store.rotation.vacaciones||[])[v.ix];
  return {ix:v.ix,shiftId:v.shiftId,label:v.label,start:vs?vs.start:'',end:vs?vs.end:''};}
function esVacacionSh(sh){return !!sh&&/vacaci/i.test(String(sh.name||''));}
/* LOS DÍAS DE VACACIONES GASTADOS: de lunes a viernes, los que has puesto tú (por periodo o pintando el día como
   «Vacaciones»), sin contar festivos, en el año de residencia que acaba el último día de R1 */
function vacGastados(){
  const fin=parseDate(finR1()),tope=Math.max(0,+((store.rotation||{}).vacDias)||22);if(!fin)return {n:0,tope:tope,desde:'',hasta:''};
  const ini=addDays(new Date(fin.getFullYear()-1,fin.getMonth(),fin.getDate(),12),1),fest=((store.ahorro||{}).festivos)||[];let n=0;
  for(let d=new Date(ini.getTime());d<=fin;d=addDays(d,1)){const w=d.getDay(),k=iso(d);if(w===0||w===6||fest.indexOf(k)>=0)continue;
    const inf=dayInfo(k);if(inf.vac||(inf.ov&&esVacacionSh(shiftById(inf.shiftId))))n++;}
  return {n:n,tope:tope,desde:iso(ini),hasta:iso(fin)};}
function vacDays(y,m){return monthDays(y,m).filter(function(d){return d.vac;}).length;}
function addVacation(start,end,label){
  let s0=parseDate(start),e0=parseDate(end);
  if(!s0||!e0)return 'pon dos fechas válidas (aaaa-mm-dd)';
  if(e0<s0){const t=s0;s0=e0;e0=t;}   /* si el fin queda antes que el inicio, se giran: nunca un rango al revés */
  if(!store.rotation.vacaciones)store.rotation.vacaciones=[];
  store.rotation.vacaciones.push({start:iso(s0),end:iso(e0),label:String(label||'').trim()});
  const n=Math.round((Date.UTC(e0.getFullYear(),e0.getMonth(),e0.getDate())
    -Date.UTC(s0.getFullYear(),s0.getMonth(),s0.getDate()))/86400000)+1;
  save();render();return n+' día(s) marcados como vacaciones del '+s0.getDate()+' '+MON[s0.getMonth()]+' al '+e0.getDate()+' '+MON[e0.getMonth()]+'. La jornada y las guardias de esos días se dan por no puestas';}
function delVacation(ix){if(!store.rotation.vacaciones)return 'no hay vacaciones apuntadas';
  store.rotation.vacaciones.splice(+ix,1);save();render();return 'vacaciones quitadas';}
function jornadaEn(wday,shiftId,override){
  /* la jornada base del mes (8:00–15:00 de lunes a viernes), para el día que sea
     vale también en los días con hora propia: el entreno de la mañana no quita que luego trabajes */
  const j=store.rotation&&store.rotation.jornada;if(!j||!j.start||!j.end)return null;
  if(wday==null||wday<0)return null;
  if(j.workdays&&j.workdays.length&&j.workdays.indexOf(wday)<0)return null;
  const sh=shiftById(shiftId);if(!sh)return null;
  if(isGuardia(sh))return null;
  if(/saliente|post ?-?guardia|vacacion|festiv/i.test(sh.name||''))return null;
  /* un día libre PUESTO POR TI es de verdad: no se trabaja; si solo lo dice la plantilla, sí entra la jornada */
  const descanso=/libre|descanso|asuntos|franco|vacante/i.test(sh.name||'');
  if(descanso&&(override||j.aplicaLibres===false))return null;
  return {start:j.start,end:j.end};}
function jornadaOf(dateStr,infOpt){
  const d=parseDate(dateStr);if(!d)return null;
  const inf=infOpt||dayInfo(dateStr);
  return jornadaEn(d.getDay(),inf.shiftId,!!dayOverride(dateStr));}
function diaLaborableCerca(desdeOpt){
  /* el primer día, de hoy en adelante, que es laborable de TU jornada. Lo usan las pruebas —y
     cualquier cosa que necesite «un día con jornada»— para no depender de qué día se ejecuten:
     en sábado no hay jornada de la que salir y media prueba del viaje caía por eso. */
  const j=(store.rotation&&store.rotation.jornada)||{};
  const wd=(j.workdays&&j.workdays.length)?j.workdays:[1,2,3,4,5];
  let d=parseDate(desdeOpt||'')||new Date();
  for(let i=0;i<8;i++){const x=addDays(d,i);if(wd.indexOf(x.getDay())>=0)return iso(x);}
  return iso(d);}
function baseWorkday(dateStr){
  /* si el hueco está vacío y es un laborable de tu jornada, el día es «Día de trabajo» con sus horas */
  const j=store.rotation&&store.rotation.jornada;if(!j||!j.start||!j.end)return null;
  const d=parseDate(dateStr);if(!d)return null;
  if(j.workdays&&j.workdays.length&&j.workdays.indexOf(d.getDay())<0)return null;
  return (shiftById('sh-t')||store.shifts.filter(function(x){return /trabajo/.test(x.name||'');})[0]||{}).id||null;}
function dayInfo(dateStr){
  const ov=dayOverride(dateStr);
  const vac=ov?null:vacationOf(dateStr);
  const auto=ov||vac?null:shiftForDate(dateStr);
  let raw=ov?(ov.shift||null):(vac?vac.shiftId:(auto?auto.shiftId:null));
  /* POR FECHA, LAS GUARDIAS LAS PONES TÚ. El ciclo de 4 semanas traía sus propias guardias (sin tipo)
     y salientes, y se mezclaban con las del mes: 8 de 6, «2 sin tipo» y salientes dobles (el del
     ciclo y el de tu guardia). Ahora, con fechas, el ciclo solo pone trabajo, fuerza y libre: un día
     de guardia o saliente del ciclo queda como día de trabajo (entre semana) o libre (finde) */
  /* LAS VACACIONES LAS PONES TÚ: un día de vacaciones que venga del ciclo es un día de trabajo (o libre en finde) */
  if(auto&&raw&&esVacacionSh(shiftById(raw))){const d=parseDate(dateStr),fin=d&&(d.getDay()===0||d.getDay()===6);
    raw=((fin?shiftByCode('L'):shiftByCode('T'))||{}).id||null;}
  /* EN NINGÚN MODO: con las semanas tipo (el modo de serie) el ciclo seguía poniendo guardias y salientes en los
     meses que aún no habías pintado. Las guardias las pintas tú, mes a mes */
  if(auto&&raw){const sh=shiftById(raw);
    if(sh&&(isGuardia(sh)||esSaliente(sh))){const d=parseDate(dateStr),fin=d&&(d.getDay()===0||d.getDay()===6);
      raw=((fin?shiftByCode('L'):shiftByCode('T'))||{}).id||null;}}
  const shiftId=raw||(!ov&&!vac?baseWorkday(dateStr):null);
  return {shiftId:shiftId,auto:!ov&&!vac,ov:ov,pat:auto?auto.pat:null,day:auto?auto.day:null,
          guard:ov&&ov.guard?ov.guard:'',vac:vac,rhythm:rhythmOf(shiftId,dateStr)};}
function sleepOf(dateStr,infOpt){
  const inf=infOpt||dayInfo(dateStr);const rh=inf.rhythm||{};
  const o={bed:rh.sleep||'',wake:rh.wake||'',h:(rh.sleep&&rh.wake)?sleepHours(rh.sleep,rh.wake):null};
  /* LA CAMA ASEGURA TU MÍNIMO DE SUEÑO hasta la hora de levantarte de mañana (salvo la noche de guardia): el día
     libre a las 00:30 y mañana a trabajar a las 06:50 daba 6 h 20. Si tu hora de siempre no llega, se adelanta */
  const shD=shiftById(inf.shiftId);
  if(dateStr&&o.bed&&!(shD&&isGuardia(shD))){const sig=nextIso(dateStr),wS=wakeRitmo(sig);
    if(wS!=null){const c=suenoCfg(),lim=wS*60+1440-(c.min*60+c.latencia);let bm=mins(o.bed);if(bm!=null&&bm<12*60)bm+=1440;
      if(bm!=null&&bm>lim){o.bed=hm(((lim%1440)+1440)%1440);o.adelantada=true;}}}
  const sal=dateStr?salidaDeGuardia(dateStr):null;
  if(!sal)return o;
  /* El día de después de una guardia esa mañana no vienes de dormir: vienes de trabajar. Lo que
     hay son DOS sueños —la siesta al llegar a casa y, por la noche, el de siempre para el día
     siguiente—, y la app contaba como sueño las horas que estabas en el hospital. */
  /* LA SIESTA DEL SALIENTE SE APUNTA A MANO: no se sabe lo que vas a dormir. Hasta que la apuntes (en «¿cómo has
     dormido?», la parte de después de la guardia) queda un hueco sugerido al llegar, sin hora de fin */
  const s0=mins(sal.sale),r=dateStr?suenoReal(dateStr):null,sMin=r&&+r.siesta>0?Math.round(+r.siesta*60):0;
  if(s0!=null){const de=s0+trayectoMin()+20;   /* 20 min para comer algo ligero al llegar */
    if(sMin){o.siesta={de:hm(de),a:hm(de+sMin),min:sMin};o.wake=o.siesta.a;}
    else{o.siestaPend={de:hm(de)};o.wake='';}}
  else o.wake='';
  const sig=nextIso(dateStr);
  o.wakeSig=sig?((rhythmOf(dayInfo(sig).shiftId,sig)||{}).wake||''):'';
  o.noche=(o.bed&&o.wakeSig)?sleepHours(o.bed,o.wakeSig):null;
  /* lo de ESE día es lo dormido en la guardia (≈2 h si no lo apuntas) + la siesta. Antes se le
     sumaba la noche de hoy, que aún no ha pasado, y salía «dormiste 13h18» */
  o.h=Math.round((2+(o.siesta?o.siesta.min/60:0))*60)/60;
  return o;}
function suenoCfg(){const d={min:8,cenaMin:90,cenaMax:180,latencia:10,siesta:360};   /* 6 h de siesta del saliente: lo pediste así (ver normalize) */const o=store.sueno||{};
  ['min','cenaMin','cenaMax','latencia'].forEach(function(k){if(typeof o[k]==='number'&&o[k]>0)d[k]=o[k];});
  /* la siesta del saliente puede ser 0 (hay quien aguanta del tirón), así que no vale el >0 */
  if(typeof o.siesta==='number'&&o.siesta>=0&&o.siesta<=480)d.siesta=o.siesta;
  /* mientras pruebas «siesta de 3 h» (2 semanas), la siesta es esa; al acabar vuelve la tuya sola */
  if(siesta3On())d.siesta=180;
  d.avisoCama=!!o.avisoCama;
  d.avisoLloret=!!o.avisoLloret;d.avisoSalir=!!o.avisoSalir;   /* al .ics, apagados de serie */
  d.adelanto=o.adelanto!==false;   /* La noche: adelantar la cama 15 min cada 3 días (encendido de serie) */
  d.conduce=o.conduce===true;   /* «no tengo carné»: por defecto vuelves en transporte, no conduciendo */
  return d;}
function siesta3On(){
  /* la prueba «siesta de 3 h»: manda solo sus 14 días (desde el día que empezó), aunque no la cierres */
  const l=store.sueno.pruebas;if(!Array.isArray(l))return null;
  const hoy=iso(new Date());
  return l.filter(function(x){if(!x||x.id!=='siesta3'||x.fin||!x.desde)return false;
    const fin=iso(addDays(parseDate(x.desde),14));return x.desde<=hoy&&hoy<fin;})[0]||null;}
function mins(t){const m=/^(\d{1,2}):(\d{2})$/.exec(String(t||'').trim());return m?(+m[1])*60+(+m[2]):null;}
function hm(m){const x=((Math.round(m)%1440)+1440)%1440;return String(Math.floor(x/60)).padStart(2,'0')+':'+String(x%60).padStart(2,'0');}
function acostarsePara(wake){/* hora de ENANAS en la cama para dormir el mínimo: si te levantas a las X, a la cama a X-mín-latencia */
  const c=suenoCfg(),w=mins(wake);if(w==null)return '';return hm(w-(c.min*60+c.latencia));}
function ventanaCena(bed){/* cenar entre 3 h y 1,5 h antes de dormir para que la digestión no robe sueño */
  const c=suenoCfg(),b=mins(bed);if(b==null)return null;return {from:hm(b-c.cenaMax),to:hm(b-c.cenaMin)};}
function despertarBase(){const rh=rhythmOf('sh-t')||{};return rh.wake||(store.rhythm&&store.rhythm['sh-t']&&store.rhythm['sh-t'].wake)||'06:50';}
function nightOf(dateStr,slOpt){
  /* qué toca esa noche: acostarse sugerido, hora real, horas dormidas y ventana de cena */
  const sl=slOpt||sleepOf(dateStr),c=suenoCfg();
  const wake=sl.wake,bed=sl.bed,rec=acostarsePara(sl.siesta||sl.siestaPend?(sl.wakeSig||''):wake);   /* saliente: 15:35 − 8 h daba «a la cama a las 07:25» */
  return {wake:wake,bed:bed,rec:rec,h:sl.h,min:c.min,corto:sl.h!=null&&sl.h<c.min,
    cena:ventanaCena(rec||bed||''),falta:(sl.h!=null&&sl.h<c.min)?Math.round((c.min-sl.h)*60):0};}
let _monthDaysCache={},_monthDaysTick=-1;
function nombreDia(key,sh){
  /* con la regla «guardia en sábado → saliente el lunes», el domingo sales del hospital pero estaba
     puesto «libre», y el lunes «Saliente» sin venir de ninguna guardia. En la casilla se dice lo que es */
  const v=(store.rotation.daySet||{})[key],sal=salidaDeGuardia(key);
  if(v&&typeof v==='object'&&v.auto==='pos'){
    if(sal&&!esSaliente(sh))return 'Sales · libre';
    if(!sal&&esSaliente(sh))return 'Libranza';}
  return sh.name;}
function monthDays(y,m){
  if(_monthDaysTick!==_renderTick){_monthDaysCache={};_monthDaysTick=_renderTick;}
  const mk=y+'-'+m;
  if(_monthDaysCache[mk])return _monthDaysCache[mk];
  const out=[],first=new Date(y,m,1,12,0,0,0),len=new Date(y,m+1,0).getDate();
  for(let i=0;i<len;i++){
    const d=new Date(y,m,1+i,12,0,0,0),key=iso(d),inf=dayInfo(key),sh=shiftById(inf.shiftId),sl=sleepOf(key,inf);
    out.push({key:key,date:d,wday:(d.getDay()+6)%7,shiftId:inf.shiftId,guard:inf.guard,over:!!inf.ov,vac:inf.vac,
      jor:jornadaOf(key,inf),inf:inf,
      color:sh?sh.color:'',icon:sh?sh.icon:'·',name:sh?nombreDia(key,sh):'sin asignar',sleepH:sl.h,bed:sl.bed,wake:sl.wake});}
  _monthDaysCache[mk]=out;
  return out;}
function monthService(y,m){
  /* el servicio que rotas ese mes y cuántas guardias tocan: lo pones tú, la app no lo inventa */
  const key=y+'-'+String(m+1).padStart(2,'0'),r=store.rotation,mm=(r.month||{})[key];
  const svc=(mm&&mm.service)||r.monthService||'';
  const n=(mm&&typeof mm.guardias==='number')?mm.guardias:(typeof r.guardiasMes==='number'?r.guardiasMes:6);
  return {key:key,service:svc,guardias:n,set:!!mm};}
function setGuardiasMes(y,m,n){
  if(y==='default'){store.rotation.guardiasMes=Math.max(0,Math.min(15,+n||0));return;}
  const key=y+'-'+String(m+1).padStart(2,'0');
  if(!store.rotation.month)store.rotation.month={};
  const cur=store.rotation.month[key]||{service:store.rotation.monthService,guardias:store.rotation.guardiasMes};
  store.rotation.month[key]={service:cur.service,guardias:Math.max(0,Math.min(15,+n||0))};}
function svcLabel(y,m){return monthService(y,m).service||'sin servicio';}
/* LAS GUARDIAS DE R1 (en Mes, bajo el abono): el año de R1 son los 12 meses que acaban el último día de R1 (de
   junio a mayo). Lo que toca es el cupo de cada mes (4 Urgencias + 2 UMI: 48 + 24) menos las que te puedes quitar al
   año (4, de Urgencias): 44 + 24. LLEVAS: los meses ya pasados cuentan lo que pintaste y, si uno quedó sin pintar,
   su cupo entero (no usabas la app); el mes en curso, lo pintado hasta ayer. QUEDAN: lo que toca menos lo que
   llevas. De lo que queda se dice cuántas ya están puestas y cuántas faltan por poner: un mes que no has pintado
   no se rellena con guardias inventadas. */
function finR1(){const f=String(store.rotation.finR1||'');return /^\d{4}-\d{2}-\d{2}$/.test(f)?f:'2027-05-31';}
function inicioR1(){const f=parseDate(finR1());return iso(new Date(f.getFullYear(),f.getMonth()-11,1));}
function quitaR1(){const q=(store.rotation||{}).quitaR1;return (typeof q==='number'&&q>=0)?Math.min(30,q):4;}
function guardiasR1(hoyK){
  hoyK=hoyK||iso(new Date());const fin=finR1(),ini=inicioR1(),tipos=gTipos(),cero=function(){const o={};tipos.forEach(function(t){o[t.code]=0;});return o;};
  const out={ini:ini,fin:fin,quita:quitaR1(),toca:cero(),llevas:cero(),hoy:cero(),quedan:cero(),puestas:cero(),porPoner:cero(),meses:[],total:0};
  const i0=parseDate(ini),f=parseDate(fin),mesHoy=hoyK.slice(0,7),suma=function(o,c,n){o[c]=(o[c]||0)+n;};
  for(let y=i0.getFullYear(),m=i0.getMonth();y<f.getFullYear()||(y===f.getFullYear()&&m<=f.getMonth());m===11?(y++,m=0):m++){
    const key=y+'-'+String(m+1).padStart(2,'0'),cupo={};repartoTipos(monthService(y,m).guardias).forEach(function(c){suma(cupo,c,1);});
    Object.keys(cupo).forEach(function(c){suma(out.toca,c,cupo[c]);});
    const pint={},antes={};let any=0;
    monthDays(y,m).forEach(function(d){if(!d.shiftId||!isGuardia(shiftById(d.shiftId)))return;
      const c=d.guard?String(d.guard).toLowerCase():(tipos[0]||{}).code;any++;suma(pint,c,1);if(d.key<hoyK)suma(antes,c,1);});
    /* el mes en curso cuenta entero, como los pasados: las guardias van por meses y a fin de mes estarán hechas (lo que
       pintaste, o su cupo si aún no lo has pintado). Así, en octubre con 6 al mes desde junio: 30, no 24 */
    const cuenta=key<=mesHoy,fila={key:key,pintado:any>0,pasado:key<mesHoy,actual:key===mesHoy,por:any?pint:(cuenta?cupo:{})};
    if(cuenta){Object.keys(fila.por).forEach(function(c){suma(out.llevas,c,fila.por[c]);});
      if(fila.actual)Object.keys(antes).forEach(function(c){suma(out.hoy,c,antes[c]);});}
    else Object.keys(pint).forEach(function(c){suma(out.puestas,c,pint[c]);});
    out.meses.push(fila);}
  /* las que te puedes quitar salen de Urgencias (si no hubiera, del siguiente tipo) */
  let q=out.quita;['urg'].concat(tipos.map(function(t){return t.code;}).filter(function(c){return c!=='urg';})).forEach(function(c){
    const x=Math.min(q,out.toca[c]||0);if(x){out.toca[c]-=x;q-=x;}});
  Object.keys(out.toca).forEach(function(c){out.quedan[c]=Math.max(0,out.toca[c]-(out.llevas[c]||0));
    out.porPoner[c]=Math.max(0,out.quedan[c]-(out.puestas[c]||0));});
  const tot=function(o){return Object.keys(o).reduce(function(a,c){return a+(o[c]||0);},0);};
  out.total=tot(out.quedan);out.totToca=tot(out.toca);out.totLlevas=tot(out.llevas);out.totPuestas=tot(out.puestas);out.totPorPoner=tot(out.porPoner);
  return out;}
function vacGastadosHTML(){
  const v=vacGastados();if(!v.desde)return '';const q=Math.max(0,v.tope-v.n);
  const lab='Vacaciones: '+v.n+' de '+v.tope+' días gastados (de lunes a viernes, del '+fechaCortaTxt(v.desde)+' al '+fechaCortaTxt(v.hasta)+'). Quedan '+q+'.';
  return '<div class="r1v'+(v.n>v.tope?' pasa':'')+'" title="'+esc(lab)+'" aria-label="'+esc(lab)+'">🏖️ <b>'+v.n+'</b> de '+v.tope+' días de vacaciones <span>· quedan '+q+' (L–V)</span></div>';}
function guardiasR1HTML(){
  const hoyK=iso(new Date()),r=guardiasR1(hoyK);if(hoyK>r.fin||hoyK<r.ini)return '';
  const tipos=gTipos().filter(function(t){return r.toca[t.code]||(t.code==='urg'||t.code==='umi');}),corto=function(t){return t.code==='urg'?'Urg':t.label;};
  const fd=function(k){const d=parseDate(k);return MON[d.getMonth()]+' '+d.getFullYear();};
  const mesN=MONTH_FULL[parseDate(hoyK).getMonth()];
  const lab='R1, de '+fd(r.ini)+' a '+fd(r.fin)+': a fin de '+mesN+' llevarás '+r.totLlevas+' de '+r.totToca+' guardias y quedarán '+r.total+' ('+
    tipos.map(function(t){return (r.quedan[t.code]||0)+' de '+t.label;}).join(' y ')+')';
  return '<details class="r1g"><summary aria-label="'+esc(lab)+'"><span class="r1t">🩺 R1 <span class="r1l">'+r.totLlevas+'/'+r.totToca+'</span> · quedan</span><b class="r1n">'+r.total+'</b>'+
      tipos.map(function(t){return '<span class="r1p '+esc(t.code)+'"><b>'+(r.quedan[t.code]||0)+'</b> '+esc(corto(t))+'</span>';}).join('')+'</summary>'+
    '<div class="r1d">'+tipos.map(function(t){const c=t.code;
        return '<p class="r1x '+esc(c)+'"><b>'+esc(t.label)+'</b>: a fin de '+esc(mesN)+', '+(r.llevas[c]||0)+' de '+(r.toca[c]||0)+(c==='urg'&&r.quita?' ('+((r.toca[c]||0)+r.quita)+' − '+r.quita+' que te quitas)':'')+
          ' · quedan '+(r.quedan[c]||0)+' <small>('+(r.puestas[c]||0)+' puestas, '+(r.porPoner[c]||0)+' por poner)</small></p>';}).join('')+
      '<p class="r1h">Mes a mes ('+tipos.map(corto).join(' + ')+'):</p>'+r.meses.map(function(m){const d=parseDate(m.key+'-01');
      return '<span class="'+(m.pasado?'pas':m.actual?'hoy':'fut')+'"><i>'+esc(MONTH_FULL[d.getMonth()].slice(0,3))+'</i>'+
        (m.pintado||m.pasado||m.actual?tipos.map(function(t){return (m.por[t.code]||0);}).join(' + ')+(m.pintado?'':' <small>cupo</small>'):'<small>sin poner</small>')+'</span>';}).join('')+
      '<p>Hasta este mes incluido: lo que pintaste (un mes sin pintar cuenta su cupo entero). Los que vienen: solo lo que tú pongas.</p></div></details>';}
function svcMesesDe(nombre,porDefecto){
  /* cada rotación puede durar lo suyo: se busca por nombre para que valga aunque el orden venga de fuera */
  const r=store.rotation,ix=(r.servicios||[]).indexOf(nombre);
  const n=(ix>=0)?Math.round(+(r.svcMeses||[])[ix]):0;
  return (n>=1&&n<=6)?n:Math.max(1,+porDefecto||1);}
function svcColor(nombre){
  /* un color estable por servicio para poder ver el año de un vistazo */
  const PAL=['#38e1ff','#7c5cff','#10b981','#f59e0b','#ef4444','#a855f7','#22d3ee','#84cc16','#f472b6'];
  const ix=(store.rotation.servicios||[]).indexOf(nombre);
  return ix>=0?PAL[ix%PAL.length]:'var(--ink2)';}
function cicloServicios(desdeY,desdeM,hastaY,hastaM,mesesPor,orden){
  /* solo devuelve el reparto, no escribe nada: así la interfaz puede enseñarlo antes de aplicarlo */
  const sv=(orden&&orden.length)?orden:(store.rotation.servicios||[]);
  const out=[];
  let cur=new Date(desdeY,desdeM,1,12),fin=new Date(hastaY,hastaM,1,12);
  if(!sv.length)return out;
  let i=0,quedan=svcMesesDe(sv[0],mesesPor);
  while(cur<=fin&&out.length<240){
    out.push({key:cur.getFullYear()+'-'+String(cur.getMonth()+1).padStart(2,'0'),
      y:cur.getFullYear(),m:cur.getMonth(),service:sv[i%sv.length]});
    cur=new Date(cur.getFullYear(),cur.getMonth()+1,1,12);
    if(--quedan<=0){i++;quedan=svcMesesDe(sv[i%sv.length],mesesPor);}}
  return out;}
function planServicios(desdeY,desdeM,hastaY,hastaM,mesesPor){
  const r=store.rotation;
  if(!r.servicios||!r.servicios.length)return 'primero escribe tus servicios (arriba): sin lista no reparto';
  const ciclo=cicloServicios(desdeY,desdeM,hastaY,hastaM,mesesPor,r.servicios);
  if(!ciclo.length)return 'el rango de meses no cuadra (¿el final es anterior al principio?)';
  if(!r.month)r.month={};
  ciclo.forEach(function(c){const prev=r.month[c.key]||{};
    r.month[c.key]={service:c.service,guardias:prev.guardias!=null?prev.guardias:r.guardiasMes};});
  save();
  return ciclo.length+' mes(es) repartidos de '+mesesPor+' en '+mesesPor+' ('+r.servicios.join(' → ')+'): '+
    ciclo.map(function(c){return MON[c.m]+' '+c.y+' · '+c.service;}).join(' · ');}
function setMonthService(y,m,svc,quota){
  /* con y='default' se cambia el valor que heredan los meses sin ajuste; si no, solo se toca ese mes */
  const n=(typeof quota==='number')?quota:(quota&&typeof quota.urg==='number')?((+quota.urg||0)+(+quota.umi||0)):
    (quota&&typeof quota.guardias==='number')?+quota.guardias:null;
  if(y==='default'){store.rotation.monthService=svc||store.rotation.monthService;
    if(n!=null)store.rotation.guardiasMes=n;return;}
  const key=y+'-'+String(m+1).padStart(2,'0');
  if(!store.rotation.month)store.rotation.month={};
  const cur=store.rotation.month[key]||{service:store.rotation.monthService,guardias:store.rotation.guardiasMes};
  store.rotation.month[key]={service:(svc===null||svc===undefined||svc===cur.service)?cur.service:svc,
    guardias:n!=null?n:(cur.guardias!=null?cur.guardias:store.rotation.guardiasMes)};}
/* ===================== guardias por tipo (Urgencias / UMI): no dependen del servicio del mes ===================== */
function gTipos(){
  /* la lista de tipos de guardia es tuya; por defecto las dos que haces */
  const r=store.rotation;
  const hora=function(v,pordef){const m=/^(\d{1,2}):(\d{2})$/.exec(String(v||'').trim());
    return m&&+m[1]<24&&+m[2]<60?(String(+m[1]).padStart(2,'0')+':'+m[2]):pordef;};
  const sane=function(t){const lab=String((t&&t.label)||'').trim().slice(0,22);
    let code=String((t&&t.code)||lab).trim().toLowerCase().replace(/[^a-z0-9]/g,'').slice(0,8);
    if(!code)code='g'+Math.random().toString(36).slice(2,5);
    /* cada tipo de guardia trae SUS horas: a qué hora es el relevo entre semana, a qué hora el fin
       de semana y cuánto se alarga la salida por el pase de guardia. Sin esto todas las guardias
       duraban 08:00–08:00 pasara lo que pasara. */
    const jd=(store.rotation&&store.rotation.jornada)||{};
    return {code:code,label:lab||code.toUpperCase(),
      relevoSem:hora(t&&t.relevoSem,hora(jd.start,'08:00')),
      relevoFinde:hora(t&&t.relevoFinde,code==='umi'?'10:00':'09:00'),
      pase:Math.max(0,Math.min(480,+((t&&t.pase)!=null?t.pase:(code==='umi'?75:0))||0)),
      /* a qué hora se come en el hospital: en la UMI de 13:45 a 14:20, en Urgencias de 14:00 a 15:00 */
      comeDe:hora(t&&t.comeDe,code==='umi'?'13:45':'14:00'),comeA:hora(t&&t.comeA,code==='umi'?'14:20':'15:00')};};
  if(!Array.isArray(r.guardiaTipos)||!r.guardiaTipos.length)
    r.guardiaTipos=[{code:'urg',label:'Urgencias'},{code:'umi',label:'UMI'}];
  r.guardiaTipos=r.guardiaTipos.map(sane);
  if(!r.cupoTipos||typeof r.cupoTipos!=='object')r.cupoTipos={urg:4,umi:2};
  return r.guardiaTipos;}
function gTipo(code){const l=gTipos();
  const c=String(code||'').trim().toLowerCase();
  return l.filter(function(t){return t.code===c;})[0]||l[0];}
function gEtiqueta(code){return code?String(code).toUpperCase().slice(0,6):'SIN TIPO';}
function gTiposTxt(g){const l=gTipos();
  return l.map(function(t){return (g.por[t.code]||0)+' '+t.label;}).join(' · ');
}
function repartoTipos(total){
  /* el cupo se reparte con la proporción que tú pongas (4+2) y sin juntar cuatro del mismo día tras otro */
  const l=gTipos(),cu=store.rotation.cupoTipos||{},bks=[],out=[];
  l.forEach(function(t){const n=Math.max(0,Math.min(15,+cu[t.code]||0)),a=[];
    for(let i=0;i<n;i++)a.push(t.code);bks.push(a);});
  if(!bks.length)bks.push([]);
  let sig=0;
  while(out.length<total&&sig<total*8+l.length){const b=bks[sig%bks.length];
    if(b&&b.length)out.push(b.shift());sig++;}
  while(out.length<total)out.push(l[out.length%l.length].code);
  return out.slice(0,total);}
function setCupoTipo(code,n){
  const l=gTipos();l.forEach(function(t){if(t.code===code)store.rotation.cupoTipos[code]=Math.max(0,Math.min(15,+n||0));});
  const suma=l.reduce(function(a,t){return a+(+store.rotation.cupoTipos[t.code]||0);},0);
  if(suma>0)store.rotation.guardiasMes=suma;
  return suma;}
function setGuardiaTipo(dateStr,code){
  /* poner la guardia con su tipo; el saliente del día siguiente lo sigue poniendo la app */
  const k=foodKey(dateStr);if(!k)return {ok:false,msg:'ese día todavía no tiene fecha'};
  const G=store.shifts.filter(isGuardia)[0];
  if(!G)return {ok:false,msg:'no hay ningún tipo de día marcado como guardia (míralo en «Turno y rotación»)'};
  if(code===null||code===''){setDayOverride(k,null);save();render();
    return {ok:true,msg:'guardia quitada del '+k+' (y su saliente automático, si lo puso la app)'};}
  const t=gTipo(code);
  setDayOverride(k,G.id,t.code);save();render();
  const sd=saltoDia(),cae=parseDate(k)&&parseDate(k).getDay()===sd.from;
  return {ok:true,msg:'guardia de '+t.label+' el '+k.slice(8)+' '+MON[+k.slice(5,7)-1]+
    (store.rotation.autoPos!==false?(' · el '+(cae?DOWN0[sd.to]:'día siguiente')+' queda saliente solo')
      :' · el post-guardia automático está apagado: lo pones tú')};}
function setHorasTipo(code,campo,valor){
  /* las horas de cada tipo de guardia: el relevo entre semana, el del fin de semana y el pase */
  const t=gTipos().filter(function(x){return x.code===code;})[0];
  if(!t)return 'ese tipo de guardia no existe';
  if(campo==='pase'){t.pase=Math.max(0,Math.min(480,Math.round(+valor||0)));
    save();render();
    return t.label+': '+(t.pase?('sales '+fmtHM(t.pase)+' más tarde por el pase de guardia'):'sin pase de guardia');}
  const m=/^(\d{1,2}):(\d{2})$/.exec(String(valor||'').trim());
  if(!m||+m[1]>23||+m[2]>59)return 'pon la hora como 09:00';
  t[campo]=String(+m[1]).padStart(2,'0')+':'+m[2];
  save();render();
  if(campo==='comeDe'||campo==='comeA')return t.label+': comes de '+t.comeDe+' a '+t.comeA;
  return t.label+': relevo '+(campo==='relevoSem'?'de lunes a viernes':'de sábado y domingo')+' a las '+t[campo];}
function renombraTipo(code,label){
  const l=gTipos(),t=l.filter(function(x){return x.code===code;})[0];
  if(!t)return 'ese tipo no existe';
  t.label=String(label||'').trim().replace(/\s+/g,' ').slice(0,22)||t.code.toUpperCase();
  save();render();return 'tipo renombrado: '+t.label;}
function addGuardiaTipo(nombre){
  /* por si en tu sitio hay una tercera clase de guardia (o las llaman de otra manera) */
  const n=String(nombre||'').trim().replace(/\s+/g,' ');
  if(!n)return {ok:false,msg:'escribe antes el nombre del tipo de guardia (p. ej. «Guardias de placa»), no lo invento yo'};
  const l=gTipos();
  if(l.some(function(t){return String(t.label).toLowerCase()===n.toLowerCase();}))
    return {ok:false,msg:'«'+n+'» ya está en la lista'};
  let code=n.toLowerCase().normalize('NFD').replace(/[^a-z0-9]/g,'').slice(0,8);
  if(!code)code='t'+(l.length+1);
  /* un número distinto en cada vuelta: antes probaba siempre el mismo y, si también estaba, no salía nunca */
  const base=code.slice(0,6);for(let i=2;l.some(function(t){return t.code===code;});i++)code=base+i;
  l.push({code:code,label:n.slice(0,22)});
  store.rotation.cupoTipos[code]=0;
  save();render();
  return {ok:true,msg:'añadido «'+n.slice(0,22)+'» (se llama '+code+'): ponle cuántas tocan y sale en cada día'};}
/* ===================== a qué hora se entra y se sale de guardia =====================
   Una guardia no dura lo mismo según el día en que cae ni según de qué sea, y de ahí salía el
   error que se veía en pantalla: el turno decía 08:00–08:00 siempre, cuando en realidad

     · entre semana entras a las 8:00 a tu JORNADA normal y a las 15:00 empieza la guardia;
     · el sábado y el domingo entras directamente a la hora del relevo (9:00 en urgencias,
       10:00 en UMI), sin jornada previa;
     · y SALES a la hora del relevo DEL DÍA EN QUE SALES —no del día en que entraste—, porque esa
       es la hora a la que entra el siguiente: 8:00 si es laborable, 9:00/10:00 si es finde;
     · en UMI, además, hay pase de guardia: se sale un rato más tarde.

   Con esa única regla salen todos los casos: viernes → sábado a las 9:00 (urgencias) o 10:00
   (UMI), sábado → domingo a la misma hora, domingo → lunes a las 8:00 en los dos. */
function esDiaDeJornada(d){
  const j=store.rotation&&store.rotation.jornada;
  if(!j||!j.start||!j.end)return false;
  const wd=(j.workdays&&j.workdays.length)?j.workdays:[1,2,3,4,5];
  return wd.indexOf(d.getDay())>=0;}
function horaRelevo(t,d){
  /* a qué hora se hace el cambio de guardia ESE día */
  /* entre semana o finde según tus días de trabajo, aunque la jornada no tenga hora: con la entrada
     vacía, todas las guardias salían con el relevo de finde (9:00 a 9:00 un martes) */
  const j=store.rotation&&store.rotation.jornada,wd=(j&&j.workdays&&j.workdays.length)?j.workdays:[1,2,3,4,5];
  return wd.indexOf(d.getDay())>=0?(t.relevoSem||(j&&j.start)||'08:00'):(t.relevoFinde||'09:00');}
function guardiaHoras(dateStr,tipoCode){
  /* desde: cuándo pisas el hospital · guardia: cuándo empieza la guardia propiamente
     sale:  cuándo te vas al día siguiente, con el pase ya sumado */
  const d=parseDate(dateStr);if(!d)return null;
  const t=gTipo(tipoCode),j=store.rotation&&store.rotation.jornada;
  const conJornada=esDiaDeJornada(d);
  const rel=mins(horaRelevo(t,addDays(d,1)));
  const pase=Math.max(0,Math.min(480,+t.pase||0));
  return {tipo:t,code:t.code,
    desde:conJornada?j.start:horaRelevo(t,d),
    guardia:conJornada?j.end:horaRelevo(t,d),
    relevo:rel==null?'':hm(rel),
    sale:rel==null?'':hm(rel+pase),
    pase:pase};}
let _salidaCache={},_salidaTick=-1;
function salidaDeGuardia(dateStr){
  /* el día DESPUÉS de una guardia no empieza en casa: de 00:00 hasta que te relevan sigues
     trabajando. Vale aunque ese día no esté marcado como saliente —si la guardia cae en sábado el
     saliente se pasa al lunes, pero el domingo por la mañana sales del hospital igual—. */
  if(!dateStr)return null;
  if(_salidaTick!==_renderTick){_salidaCache={};_salidaTick=_renderTick;}
  if(Object.prototype.hasOwnProperty.call(_salidaCache,dateStr))return _salidaCache[dateStr];
  let out=null;
  const d=parseDate(dateStr);
  if(d){const ant=iso(addDays(d,-1)),inf=dayInfo(ant),sh=shiftById(inf.shiftId);
    if(sh&&isGuardia(sh))out=guardiaHoras(ant,inf.guard);}
  _salidaCache[dateStr]=out;
  return out;}
function esSaliente(sh){return !!sh&&/saliente|post ?-?guardia/i.test(String(sh.name||''));}
/* ===================== la comida principal no está a una hora fija =====================
   La hora de comer no la manda el tipo de día: la manda lo que haces ese día.
     · Si entrenas, la comida principal cae después del entreno: 18:00–18:30.
     · Si no entrenas, al acabar la jornada de 8 a 15: 14:00–15:00.
     · Y el día que sales de guardia, cuando te despiertas de la siesta — no a una hora del reloj,
       porque esa hora depende de a qué hora te relevaron.
   Antes era una lista de horas fijas por tipo de día, y por eso el mismo «Día de trabajo» decía
   siempre 14:30 entrenaras o no. Los valores se cambian en Ajustes; estos son los de fábrica. */
function viajeCfg(){
  /* IR Y VOLVER. `min` es lo que tardas de casa al trabajo (y al revés); `bus` la hora del
     transporte que sueles coger, y `antes` los minutos que quieres estar en la parada antes de que
     pase. De ahí sale a qué hora tienes que salir de casa y a qué hora llegas de vuelta. */
  const d={min:20,bus:'07:35',antes:4,on:true},o=(store.rotation&&store.rotation.viaje)||{};
  if(+o.min>=0&&+o.min<=180)d.min=Math.round(+o.min);
  if(/^\d{1,2}:\d{2}$/.test(String(o.bus||'')))d.bus=o.bus; else if(o.bus==='')d.bus='';
  if(+o.antes>=0&&+o.antes<=30)d.antes=Math.round(+o.antes);
  if(o.on===false)d.on=false;
  d.taxi=o.taxi!==false;   /* de serie se da por hecho el taxi, hasta que lo cambies en el hábito o en Ajustes */
  d.taxiEur=+o.taxiEur>=0&&+o.taxiEur<=100?Math.round(+o.taxiEur*100)/100:10;   /* lo que cuesta un taxi al hospital: con eso el taxi es un gasto en Dinero */
  return d;}
function salirDeCasaTxt(){
  /* «salir de casa 7:30 · bus 7:35», que es exactamente lo que pidió y nada más */
  const v=viajeCfg();
  if(!v.on||!v.bus)return '';
  const b=mins(v.bus);if(b==null)return '';
  return 'salir de casa '+hm(b-v.antes)+' · bus '+fmtTimeOut(v.bus);}
function llegasACasa(dateStr,infOpt){
  /* a qué hora estás de vuelta: el fin de la jornada más el viaje */
  const jor=jornadaOf(dateStr,infOpt);
  if(!jor||!jor.end)return null;
  const f=mins(jor.end);if(f==null)return null;
  const v=viajeCfg();
  return f+(v.on?v.min:0);}
function comidasCfg(){
  const d={conEntreno:{de:'18:00',a:'18:30'},sinEntreno:{de:'14:00',a:'15:00'},trasSiesta:30};
  const o=store.comidas||{},hh=/^\d{1,2}:\d{2}$/;
  ['conEntreno','sinEntreno'].forEach(function(k){
    if(o[k]&&hh.test(String(o[k].de||''))&&hh.test(String(o[k].a||'')))d[k]={de:o[k].de,a:o[k].a};});
  if(typeof o.trasSiesta==='number'&&o.trasSiesta>=0&&o.trasSiesta<=180)d.trasSiesta=o.trasSiesta;
  return d;}
function hayEntrenoEn(dateStr,infOpt){
  /* cuenta como entreno la rutina que toca ese día, el segundo entreno (piscina y demás) y que el
     propio tipo de día sea de fuerza */
  if(!dateStr)return false;
  const inf=infOpt||dayInfo(dateStr);
  if(rutinaDeFecha(dateStr))return true;
  const s2=diaSegundo(dateStr,inf);if(s2&&s2.on)return true;
  const sh=shiftById(inf.shiftId);
  return !!(sh&&/fuerza|entreno|gym/i.test(sh.name||''));}
function finEntrenoDe(dateStr,infOpt){
  /* A QUÉ HORA ACABAS DE ENTRENAR ese día (el más tardío de los dos entrenos). Las mismas horas que
     usa el carril, para que la comida y el bloque pintado no se contradigan. */
  if(!dateStr)return null;
  const inf=infOpt||dayInfo(dateStr),sh=shiftById(inf.shiftId);
  if(!sh)return null;
  let fin=null;
  const jor=jornadaOf(dateStr,inf);
  const esF=/fuerza|entreno|gym/i.test(sh.name||'')||!!rutinaDeFecha(dateStr);
  if(esF){
    const propias=sh.start&&!(jor&&jor.start===sh.start);
    const hi=propias?sh.start:((gymS()||{}).hora||'');
    const m=mins(hi);
    if(m!=null){
      const f=(propias&&sh.end&&sh.end>sh.start)?mins(sh.end):(m+gymDur(dateStr));
      if(f!=null&&(fin==null||f>fin))fin=f;}}
  const g2=diaSegundo(dateStr,inf);
  if(g2&&g2.on){const m=mins(g2.hora||'15:30');
    if(m!=null&&(fin==null||m+60>fin))fin=m+60;}
  return fin;}
function comidaPrincipalDe(dateStr,infOpt){
  if(!dateStr)return null;
  const inf=infOpt||dayInfo(dateStr),c=comidasCfg();
  const sal=salidaDeGuardia(dateStr);
  if(sal){const sl=sleepOf(dateStr,inf);
    if(sl&&sl.siesta){const m=mins(sl.siesta.a);
      if(m!=null)return {de:hm(m+c.trasSiesta),a:hm(m+c.trasSiesta+60),por:'siesta'};}}
  /* EL DÍA DE GUARDIA SE COME EN EL HOSPITAL, a la hora de ese tipo de guardia (UMI 13:45–14:20,
     Urgencias 14:00–15:00). Antes salía la hora de llegar a casa, y ese día no vuelves */
  const shG=shiftById(inf.shiftId);
  if(shG&&isGuardia(shG)){const t=gTipo(inf.guard);return {de:t.comeDe,a:t.comeA,por:'guardia'};}
  /* LA COMIDA POST-ENTRENO SOLO MANDA SI EL ENTRENO ES EL QUE LA EMPUJA. Con un entreno de fuerza a
     las 6:30 de la mañana la app ponía «comida post-entreno · 18:00»: el entreno había acabado a
     las ocho y la comida caía cuatro horas tarde. Si el entreno acaba antes de tu hora normal de
     comer, no cuenta: manda la jornada. */
  if(hayEntrenoEn(dateStr,inf)){
    const finG=finEntrenoDe(dateStr,inf),puesta0=mins(c.sinEntreno.de);
    if(finG==null||puesta0==null||finG>puesta0)
      return {de:c.conEntreno.de,a:c.conEntreno.a,por:'entreno'};}
  /* LA COMIDA NO PUEDE CAER DENTRO DE LA JORNADA. Esto decía «al salir de la jornada» y usaba una
     hora FIJA: con jornada de 8 a 15 te ponía a comer en casa a las 14:00, que es imposible —a esa
     hora estás en el hospital—. Ahora la hora de la lista es lo PRONTO que comerías, y si la
     jornada acaba más tarde manda la jornada: fin + lo que tardas en llegar a casa. */
  const jor=jornadaOf(dateStr,inf);
  if(jor&&jor.end){
    const enCasa=llegasACasa(dateStr,inf);
    const puesta=mins(c.sinEntreno.de);
    if(enCasa!=null&&puesta!=null&&enCasa>puesta){
      const dur=Math.max(30,(mins(c.sinEntreno.a)||(puesta+60))-puesta);
      return {de:hm(enCasa),a:hm(enCasa+dur),por:'llegar'};}
    return {de:c.sinEntreno.de,a:c.sinEntreno.a,por:'jornada'};}
  /* un día libre no tiene jornada de la que salir: la hora es la misma, pero no se inventa el motivo */
  return {de:c.sinEntreno.de,a:c.sinEntreno.a,por:'normal'};}
function esComidaPrincipal(slot){
  /* cuál de las tomas del día es «la comida»: la que se llama así, y no la media mañana */
  const l=String((slot&&slot.label)||'');
  return /comida/i.test(l)&&!/media\s*ma/i.test(l);}
function horaDeToma(dateStr,slot,cpOpt){
  /* la hora que hay que ENSEÑAR de esa toma: la de la lista, salvo que sea la comida principal y
     ese día tenga una hora propia */
  const cp=cpOpt!==undefined?cpOpt:(dateStr?comidaPrincipalDe(dateStr):null);
  if(cp&&esComidaPrincipal(slot))return cp.de;
  /* el saliente: lo de «post-guardia» es algo ligero AL LLEGAR, antes de la siesta (estaba a las
     11:00 fijas, en mitad de ella) */
  if(dateStr&&slot&&/post.?guardia|al llegar/i.test(slot.label||'')){const sal=salidaDeGuardia(dateStr),m=sal&&mins(sal.sale);
    if(m!=null)return hm(m+trayectoMin());}
  const ll=dateStr&&slot&&/cena/i.test(slot.label||'')?lloretDe(dateStr):null;
  if(ll){const m=mins(ll.hora);if(m!=null)return hm(m-LL_CENA_ANTES);}
  return (slot&&slot.time)||'';}
function trayectoMin(){
  /* LO QUE TARDAS DEL TRABAJO A CASA, DE UN SOLO SITIO. Había dos números para lo mismo: este, que
     salía de las horas «salir→llegar» del tipo de día de guardia, y el de Ajustes → Ir y volver.
     Cambiabas uno y el otro seguía como estaba, y la siesta del saliente se calculaba con este,
     así que tocar el de Ajustes no la movía. Manda el de Ajustes, que es el que se ve y se toca.
     Las horas del tipo de día se quedan de reserva para cuando lo tengas apagado. */
  const v=viajeCfg();
  if(v.on&&v.min>0)return v.min;
  const rh=(store.rhythm&&store.rhythm['sh-g'])||{};
  const a=mins(rh.leave),b=mins(rh.arrive);
  const t=(a!=null&&b!=null)?((b-a+1440)%1440):15;
  return (t>0&&t<=120)?t:15;}
function bloquesTrabajo(dateStr,inf){
  /* Todo lo que se trabaja ESE día, ya partido por la medianoche y en minutos. Es una LISTA porque
     un día puede tener dos cosas: la jornada y luego la guardia encima, o la salida de la guardia
     de ayer y nada más. Antes esto era una sola pareja de horas sacada del tipo de día, y por eso
     el saliente salía como si trabajaras de 9 a 13 cuando lo que hay es trabajo hasta el relevo. */
  const out=[];
  if(!dateStr){
    const sh0=shiftById(inf&&inf.shiftId);
    if(sh0&&sh0.start){const a=mins(sh0.start);let b=mins(sh0.end);
      if(a!=null&&b!=null){if(b<=a)b=1440;
        out.push({de:a,a:b,tipo:isGuardia(sh0)?'guard':'work',txt:(isGuardia(sh0)?'guardia ':'trabajo ')+sh0.start+'–'+sh0.end});}}
    return out;}
  inf=inf||dayInfo(dateStr);
  const sh=shiftById(inf.shiftId);
  const sal=salidaDeGuardia(dateStr);
  if(sal&&mins(sal.sale)!=null&&mins(sal.sale)>0)
    out.push({de:0,a:mins(sal.sale),tipo:'guard',pase:sal.pase||0,   /* la agenda dice «con el pase» con esto */
      txt:'guardia de ayer hasta el relevo de las '+sal.sale+(sal.pase?(' (con pase de '+fmtHM(sal.pase)+')'):'')});
  if(sh&&isGuardia(sh)){
    const g=guardiaHoras(dateStr,inf.guard);
    if(g){const d0=mins(g.desde),g0=mins(g.guardia);
      if(d0!=null&&g0!=null&&g0>d0)out.push({de:d0,a:g0,tipo:'work',txt:'jornada '+g.desde+'–'+g.guardia});
      if(g0!=null)out.push({de:g0,a:1440,tipo:'guard',txt:'guardia desde las '+g.guardia+', sales a las '+g.sale});}
  }else if(!(sal&&esSaliente(sh))){
    /* el saliente ya tiene sus horas de verdad arriba: las suyas propias sobran y estorban */
    const jor=jornadaOf(dateStr,inf);
    const propio=(sh&&sh.start)?{start:sh.start,end:sh.end}:null;
    const mete=function(w,txt){if(!w||!w.start)return;
      const a=mins(w.start);let b=mins(w.end);
      if(a==null||b==null)return;if(b<=a)b=1440;
      out.push({de:a,a:b,tipo:'work',txt:txt+' '+w.start+'–'+w.end});};
    /* un «Día de fuerza» es entreno DE 6:30 A 8:00 *Y* jornada de 8 a 15: antes solo salía lo
       primero y el resto del día se pintaba vacío, como si no trabajaras */
    /* las horas propias son el ENTRENO solo en un día de fuerza; en cualquier otro son su jornada.
       Antes se llamaban «entreno» siempre, y un «Día de trabajo» de 8 a 15 salía en Hoy como entreno */
    mete(propio,/fuerza|entreno|gym/i.test((sh&&sh.name)||'')?'entreno':'jornada');
    if(jor&&(!propio||propio.start!==jor.start||propio.end!==jor.end))mete(jor,'jornada');
    if(!propio&&!jor&&false)return out;}
  return out;}
function horasDelDiaTxt(dateStr,inf){
  /* la misma lista, en una línea: «8:00–15:00 · guardia 15:00→09:15» */
  const bs=bloquesTrabajo(dateStr,inf);
  if(!bs.length)return '';
  const sal=dateStr?salidaDeGuardia(dateStr):null;
  const sh=shiftById((inf||dayInfo(dateStr||'')).shiftId);
  if(sh&&isGuardia(sh)&&dateStr){
    const g=guardiaHoras(dateStr,(inf||dayInfo(dateStr)).guard);
    if(g)return (g.desde!==g.guardia?(fmtTimeOut(g.desde)+'–'+fmtTimeOut(g.guardia)+' · '):'')+
      'guardia '+fmtTimeOut(g.guardia)+'→'+fmtTimeOut(g.sale);}
  if(sal&&sh&&esSaliente(sh))return 'sales a las '+fmtTimeOut(sal.sale);
  return bs.map(function(b){
    return fmtTimeOut(hm(b.de))+'–'+fmtTimeOut(hm(b.a>=1440?0:b.a));}).join(' · ');}
function guardCount(y,m){
  /* las guardias van por TIPO (Urgencias / UMI, o lo que tú hayas puesto), no por el servicio del mes */
  const n={any:0,por:{},urg:0,umi:0};
  monthDays(y,m).forEach(function(d){if(d.shiftId&&isGuardia(shiftById(d.shiftId))){n.any++;
    const k=d.guard?String(d.guard).toLowerCase():'sin';
    n.por[k]=(n.por[k]||0)+1;if(k==='urg')n.urg++;if(k==='umi')n.umi++;}});
  return n;}
function slotsFor(shiftId){return store.menu[shiftId]||[];}
function slotItems(shiftId,s,key){
  /* con fecha, la semana base puede decidir esta toma (ver sbDeToma); sin fecha, es el menú del tipo */
  const sb=key?sbDeToma(shiftId,s,key):null;
  if(sb)return {items:sb.items,name:sb.meal||'semana base',meal:false,base:true};
  if(s&&s.mealId){const m=mealById(s.mealId);if(m)return {items:m.items||[],name:m.name,meal:true};}
  return {items:(s&&s.items)||[],name:null,meal:false};
}
function dishQty(items){const q={};(items||[]).forEach(it=>{if(!it||it.kind!=='dish'||!it.id)return;const d=dishById(it.id);if(!d)return;q[d.id]=(q[d.id]||0)+num(it.portions,1);});return q;}
function totals(items){const q=dishQty(items);let k=0,p=0,n=0;
  Object.keys(q).forEach(id=>{const d=dishById(id),m=q[id];k+=(d.kcal||0)*m;p+=(d.prot||0)*m;n+=m;});
  return {kcal:Math.round(k),prot:Math.round(p),parts:Math.round(n*10)/10};}
function dayTotals(shiftId){const sh=shiftById(shiftId);if(!sh)return {kcal:0,prot:0,parts:0};
  const items=[];slotsFor(shiftId).forEach(s=>items.push.apply(items,slotItems(shiftId,s).items));return totals(items);}

/* cuántas raciones toca de cada plato, y en qué tandas se convierten */
function necesidadSemana(days){
  /* cuántas raciones de cada plato pide el menú de la semana. Lo usan las tandas Y la compra: la
     compra miraba SOLO las tandas, así que un plato del menú sin sesión de cocina asignada no
     aportaba ni un ingrediente a la lista, y encima sin avisar. */
  const need={};
  (days||[]).forEach(function(d){if(!d.shiftId)return;
    const q=dishQty(d.key?itemsDelDia(d.key,null,d.shiftId):[].concat.apply([],slotsFor(d.shiftId).map(function(s){return slotItems(d.shiftId,s).items;})));
    Object.keys(q).forEach(function(id){need[id]=(need[id]||0)+q[id];});});
  /* lo que ya está cocinado no se vuelve a cocinar: con dos raciones de lentejas en la nevera, «En
     lote» mandaba cocinar otras cuatro el domingo y la Semana decía «cocinas: nada» */
  cocinadoS().forEach(function(x){if(need[x.dishId])need[x.dishId]=Math.max(0,need[x.dishId]-x.queda);});
  return need;}
function planBatches(days){
  const need=necesidadSemana(days);
  const batches={};
  store.dishes.forEach(d=>{if(!isBatch(d.batchId))return;
    const b=batchById(d.batchId);if(!b)return;
    const needP=Math.round((need[d.id]||0)*10)/10;
    const perPort=d.portions||1;
    const runs=needP>0?Math.max(1,Math.ceil(needP/perPort)):0;
    const suelo=runs>0?Math.max(needP||0,(b.minCook||0),runs*perPort):0;   /* sin nada que cocinar, 0: no «4 raciones, sobran 4» */   // nunca media receta: se hace la tanda y lo que sobra se congela
    const cooked=Math.round(suelo*10)/10;
    if(!batches[b.id])batches[b.id]={id:b.id,label:b.label,when:b.when,note:b.note,minCook:b.minCook||0,items:[],portions:0,hasNeed:false};
    batches[b.id].items.push({dish:d,needPort:needP,runs:runs,cooked:cooked});
    batches[b.id].portions+=cooked;
    if(needP>0)batches[b.id].hasNeed=true;});
  Object.keys(batches).forEach(k=>{batches[k].portions=Math.round(batches[k].portions*10)/10;});
  return batches;
}

/* ===================== la semana base =====================
   «Un menú semanal básico independiente de lo que sea ese día». El menú iba pegado al TIPO de día
   (trabajo, guardia, libre): para saber qué comías el jueves había que mirar qué tipo le tocaba y
   luego su menú. La semana base dice qué comes cada día de la semana en desayuno, comida y cena;
   el tipo de día sigue mandando en la HORA y en si va en táper. Si una casilla está vacía, manda
   el menú del tipo de día, como siempre. */
const SB_CLASES=[['desayuno','Desayuno'],['comida','Comida'],['cena','Cena']];
const SB_DIAS=['LUN','MAR','MIÉ','JUE','VIE','SÁB','DOM'];
const SB_DIAS_L=['lunes','martes','miércoles','jueves','viernes','sábado','domingo'];
/* qué parte del día se lleva cada toma, para decir «cabe en tu hueco» */
const SB_PARTE={desayuno:0.25,comida:0.4,cena:0.35};
function sbS(){
  if(!store.semBase||typeof store.semBase!=='object')store.semBase={on:true,d:{}};
  if(!store.semBase.d||typeof store.semBase.d!=='object')store.semBase.d={};
  return store.semBase;}
/* la semana que se está planeando (lunes), y la fecha de su día w (0 = lunes). Las casillas se
   siguen pidiendo por w, pero se guardan por fecha: lo del miércoles 7 no se repite el 14 */
function sbLun(){return iso(mondayOf(weekDate));}   /* la misma semana que el calendario: ‹ › de Comer la mueve */
function sbKey(w){return /^\d{4}-/.test(String(w))?String(w):iso(addDays(parseDate(sbLun()),+w||0));}
function sbCelda(w,c){const d=sbS().d[sbKey(w)];return (d&&d[c]&&Array.isArray(d[c].items))?d[c]:null;}
/* LA GUARDIA SALE DEL DÍA, NO DE LA CASILLA. La semana se guarda por día de la semana (lunes…domingo)
   y el «Hospital» se escribía en la casilla del día en que caía la guardia cuando se montó: la semana
   siguiente la guardia caía otro día y salía comida de casa en la guardia y «Hospital» en el
   saliente. Ahora la comida y la cena de un día de guardia se deducen de la fecha: hospital, o el
   táper que elijas para ESA fecha (store.gComida). Lo guardado en la casilla no se toca. */
function gComidaS(){if(!store.gComida||typeof store.gComida!=='object')store.gComida={};return store.gComida;}
function guardiaCelda(key,c){
  if(!key||(c!=='comida'&&c!=='cena')||!esDiaGuardia(key))return null;
  const id=gComidaS()[key+'|'+c],d=id&&dishById(id);
  return {items:[{kind:'dish',id:d?d.id:dishHospital().id,portions:1}],meal:'',auto:!d,guardia:true};}
function sbCeldaDia(key,c){
  /* la casilla de un día concreto: la guardia manda; si no es guardia, el «Hospital» que se quedó
     guardado de otra semana no vale (cae al menú del tipo de día) */
  const g=guardiaCelda(key,c);if(g)return g;
  const x=sbCelda(key,c),d=x&&x.items[0]&&dishById(x.items[0].id);
  return d&&d.hospital?null:x;}
function sbFechaW(w){return sbKey(w);}
function sbCeldaMia(w,c){const s=sbS(),k=sbKey(w);if(!s.d[k])s.d[k]={};if(!s.d[k][c])s.d[k][c]={items:[],meal:''};
  if(!Array.isArray(s.d[k][c].items))s.d[k][c].items=[];return s.d[k][c];}
function sbPoner(w,c,id,o){
  /* un plato en un hueco de la semana: el único sitio que lo escribe. En un día de guardia de esta
     semana lo que eliges es para ESA fecha (hospital o táper); lo automático no la toca */
  o=o||{};const kG=sbFechaW(w);
  if(guardiaCelda(kG,c)){if(o.auto)return null;const g=gComidaS();
    if(!id||id===dishHospital().id)delete g[kG+'|'+c];else g[kG+'|'+c]=id;sbS().on=true;if(o.save)save();return guardiaCelda(kG,c);}
  const cel=sbCeldaMia(w,c);cel.items=id?[{kind:'dish',id:id,portions:o.portions||1}]:[];cel.meal='';cel.auto=!!o.auto;
  sbS().on=true;if(o.save)save();return cel;}
function sbPonerItems(w,c,items,meal){
  /* varios platos (o una comida entera) en un hueco: la misma regla que sbPoner. En un día de guardia
     la comida o la cena es la de ESA fecha; antes se escribía en la casilla guardada y el plan, la
     cocina y la compra seguían diciendo «Menú del hospital» */
  const kG=sbFechaW(w);
  if(guardiaCelda(kG,c)){const x=(items||[]).filter(function(i){return i&&i.id;})[0];return sbPoner(w,c,x?x.id:'');}
  const cel=sbCeldaMia(w,c);cel.items=(items||[]).filter(function(x){return x&&x.id;}).map(function(x){return {kind:'dish',id:x.id,portions:num(x.portions,1)};});
  cel.meal=meal||'';cel.auto=false;sbS().on=true;return cel;}
function sbTiene(){const s=sbS();
  return Object.keys(s.d).some(function(w){return SB_CLASES.some(function(c){const x=sbCelda(w,c[0]);return x&&x.items.length;});});}
function sbActiva(){return !!(store&&store.semBase&&store.semBase.on&&sbTiene());}
function sbDow(key){const d=parseDate(key);return d?(d.getDay()+6)%7:-1;}
function tomaDeClase(shiftId,cls){
  /* la toma que lleva el desayuno, la comida o la cena de ese tipo de día. En la comida, la que se
     llama «comida» antes que el táper o la media mañana */
  const l=slotsFor(shiftId).filter(function(x){return claseDeToma(x.label)===cls;});
  return (cls==='comida'&&l.filter(esComidaPrincipal)[0])||l[0]||null;}
function sbDeToma(shiftId,s,key){
  /* ¿esta toma de este día la decide la semana base? Solo la PRIMERA toma de cada clase del tipo de
     día: si un tipo tiene «comida» y «táper», la semana base pone la comida y el táper sigue igual */
  if(!key||!s||!sbActiva())return null;
  const cls=claseDeToma(s.label);if(!SB_PARTE[cls])return null;
  const primero=tomaDeClase(shiftId,cls);
  if(!primero||primero.id!==s.id)return null;
  const c=sbCeldaDia(key,cls);
  return (c&&c.items.length)?c:null;}
function sbColor(d){
  /* el color es la SESIÓN de cocina (identidad), en orden fijo; «al momento» va en gris */
  if(!d||!isBatch(d.batchId))return 'var(--line)';
  const bs=store.batches.filter(function(b){return isBatch(b.id);});
  const i=bs.findIndex(function(b){return b.id===d.batchId;});
  return i>=0&&i<3?('var(--ses'+(i+1)+')'):'var(--ink2)';}
function sbKcalDia(w){let k=0;SB_CLASES.forEach(function(c){const x=sbCelda(w,c[0]);if(x)k+=totals(x.items).kcal;});return k;}
function sbConsumo(){
  /* qué plato se come qué día de la semana (0 = lunes), en raciones. De la semana base si la hay;
     si no, de lo que diga el menú de cada tipo de día esta semana */
  const out={};
  const mete=function(w,items){Object.keys(dishQty(items)).forEach(function(id){
    const q=dishQty(items)[id];(out[id]||(out[id]={}))[w]=(out[id][w]||0)+q;});};
  if(sbActiva()){weekDays().forEach(function(d,i){const w=d.key?sbDow(d.key):i;
    SB_CLASES.forEach(function(c){const x=d.key?sbCeldaDia(d.key,c[0]):sbCelda(w,c[0]);
      if(x&&x.items.length){mete(w,x.items);return;}
      /* casilla vacía: lo que diga el tipo de día, como hacen la Semana y la compra (antes «Cuándo
         cocinar» se saltaba esas lentejas de la tanda) */
      if(d.shiftId){const sl=tomaDeClase(d.shiftId,c[0]);if(sl)mete(w,slotItems(d.shiftId,sl,d.key).items);}});});return out;}
  weekDays().forEach(function(d,i){if(!d.shiftId)return;const w=d.key?sbDow(d.key):i;
    slotsFor(d.shiftId).forEach(function(s){mete(w,slotItems(d.shiftId,s,d.key).items);});});
  return out;}
function sbCopiar(){
  /* arranque: lo que comes AHORA según tus tipos de día, puesto en la semana base. Solo en los huecos. */
  const dias=weekDays();let n=0;
  dias.forEach(function(d,i){if(!d.shiftId)return;const w=d.key?sbDow(d.key):i;
    SB_CLASES.forEach(function(c){
      if((sbCelda(w,c[0])||{items:[]}).items.length)return;
      const sl=tomaDeClase(d.shiftId,c[0]);if(!sl)return;
      const inf=slotItems(d.shiftId,sl);if(!inf.items.length)return;
      const cel=sbCeldaMia(w,c[0]);
      cel.items=inf.items.filter(function(x){return x&&x.kind==='dish'&&dishById(x.id);})
        .map(function(x){return {kind:'dish',id:x.id,portions:num(x.portions,1)};});
      cel.meal=inf.meal?String(inf.name||''):'';n++;});});
  sbS().on=true;save();
  return n?(n+' casilla'+(n===1?'':'s')+' copiadas de tus tipos de día'):'no había nada que copiar: tus tipos de día no tienen platos';}
function sbRellenar(){
  /* los huecos, con lo que TÚ sueles poner en esa toma (sacado de tus menús), sin repetir plato el
     mismo día y variando entre días */
  const por=platosDeClase();let n=0;
  for(let w=0;w<7;w++)SB_CLASES.forEach(function(c,ci){
    if((sbCelda(w,c[0])||{items:[]}).items.length)return;
    const cand=Object.keys(por[c[0]]||{}).filter(function(id){return dishById(id);})
      .sort(function(a,b){return (por[c[0]][b]||0)-(por[c[0]][a]||0);});
    if(!cand.length)return;
    const yaHoy={};SB_CLASES.forEach(function(o){const x=sbCelda(w,o[0]);if(x)x.items.forEach(function(it){yaHoy[it.id]=1;});});
    const libres=cand.filter(function(id){return !yaHoy[id];});
    const id=(libres.length?libres:cand)[(w+ci)%(libres.length||cand.length)];
    const cel=sbCeldaMia(w,c[0]);cel.items=[{kind:'dish',id:id,portions:1}];cel.meal='';n++;});
  sbS().on=true;save();
  return n?(n+' hueco'+(n===1?'':'s')+' rellenado'+(n===1?'':'s')+' con lo que sueles comer ahí'):'no quedaban huecos (o tus menús no dicen qué sueles comer en cada toma)';}
function renderSemanaBase(){
  const s=sbS(),ob=objetivoMacros(),hayAlgo=sbTiene();
  const ks=[0,1,2,3,4,5,6].map(sbKcalDia);
  const conK=ks.filter(function(k){return k>0;});
  const media=conK.length?Math.round(conK.reduce(function(a,b){return a+b;},0)/conK.length):0;
  const tope=Math.max(ob.kcal?ob.kcal*1.15:0,Math.max.apply(null,ks))||1;
  const hoyW=sbDow(iso(new Date()));
  const kmax=Math.max.apply(null,ks);
  const barras=ks.map(function(k,w){
    const h=Math.round(k/tope*60);
    return '<span class="sbw" title="'+SB_DIAS_L[w]+': '+k+' kcal'+(ob.kcal?(' · objetivo '+ob.kcal):'')+'">'+
      '<b>'+(k&&k===kmax?fmtMil(k):'')+'</b><i style="height:'+Math.max(k?3:0,h)+'px"></i></span>';}).join('');
  const linea=ob.kcal?('<span class="sbobj" style="bottom:'+(Math.round(ob.kcal/tope*60)+16)+'px"><em>objetivo '+fmtMil(ob.kcal)+'</em></span>'):'';
  const usadas={};
  const celdas=SB_CLASES.map(function(c){
    return '<span class="sbm">'+esc(c[1].toUpperCase())+'</span>'+[0,1,2,3,4,5,6].map(function(w){
      const x=sbCelda(w,c[0]),its=x?x.items.filter(function(it){return dishById(it.id);}):[];
      if(!its.length)return '<button class="sbc vacio" data-a="sb-celda" data-w="'+w+'" data-c="'+c[0]+'" aria-label="'+SB_DIAS_L[w]+' '+c[1]+': vacío">+</button>';
      const d0=dishById(its[0].id);
      its.forEach(function(it){const dd=dishById(it.id);if(dd)usadas[isBatch(dd.batchId)?dd.batchId:'_']=1;});
      /* el PLATO, no el nombre de la comida armada: «Desayuno de guardia (sin cocinar)» cortado a 45 px
         no dice nada, «Porridge overnight» sí */
      const nom=d0.name;
      return '<button class="sbc" style="--s:'+sbColor(d0)+'" data-a="sb-celda" data-w="'+w+'" data-c="'+c[0]+'" '+
        'title="'+esc(its.map(function(it){const dd=dishById(it.id);return dd.name;}).join(' + '))+' · '+totals(its).kcal+' kcal">'+
        '<i>'+esc(d0.icon||'🍽')+'</i>'+esc(nomCorto(nom))+(its.length>1?(' <small>+'+(its.length-1)+'</small>'):'')+'</button>';}).join('');}).join('');
  const bs=store.batches.filter(function(b){return isBatch(b.id);});
  const ley=bs.slice(0,3).filter(function(b){return usadas[b.id];}).map(function(b,i){
    return '<span><i style="background:var(--ses'+(bs.indexOf(b)+1)+')"></i>'+esc(b.label)+'</span>';}).join('')+
    (usadas._?'<span><i style="background:var(--line)"></i>se hace al momento</span>':'');
  let pend=0;try{const cd=compraDatos();pend=Math.max(0,cd.total-cd.marcados);}catch(e){}
  $('#main').innerHTML='<div class="grid">'+
    '<div class="subcab"><button class="btn s volver" data-a="types-vista" data-v="montar">'+gymIco('atras','gico sm')+' Montar</button>'+
      '<h2 class="subtit">Semana base</h2><span class="tag b2">L–D</span></div>'+
    '<div class="card">'+
      '<div class="row" style="align-items:baseline"><b style="font-size:13px">kcal por día</b><span class="sp"></span>'+
        '<span class="mini">'+(ob.kcal?('objetivo '+fmtMil(ob.kcal)+' · '):'')+'media <b style="color:var(--ink)">'+fmtMil(media)+'</b></span></div>'+
      '<div class="sbg" role="table" aria-label="Semana base: qué comes cada día">'+
        '<div class="sbbar">'+barras+linea+'</div>'+
        SB_DIAS.map(function(n,w){return '<span class="sbh'+(w===hoyW?' hoy':'')+'">'+n+'</span>';}).join('')+
        celdas+
      '</div>'+
      (ley?('<div class="sbley">'+ley+'</div>'):'')+
      (!hayAlgo?('<div class="empty" style="margin-top:10px">Vacía. Empieza copiando lo que ya comes según tus tipos de día, o rellénala con lo que sueles poner en cada toma.</div>'):'')+
    '</div>'+
    '<label class="sbon"><input type="checkbox" data-a="sb-on"'+(s.on?' checked':'')+'> '+
      '<span><b>Manda en mis días</b><span class="mini"> · lo que pongas aquí es lo que comes ese día de la semana; el tipo de día (guardia, trabajo, libre) solo decide la hora y si va en táper. Casilla vacía: manda el tipo de día.</span></span></label>'+
    '<div class="chips">'+
      '<button class="chipx on" data-a="tab" data-t="shop">🛒 lo que falta, a la compra'+(pend?(' ('+pend+')'):'')+'</button>'+
      '<button class="chipx" data-a="types-vista" data-v="cocinar">🔪 cuándo cocinar</button>'+
      '<button class="chipx" data-a="sb-rellenar">✨ rellenar huecos</button>'+
      '<button class="chipx" data-a="sb-copiar">⤵ copiar de mis tipos de día</button>'+
    '</div>'+
  '</div>';}
function platoCortoSem(t){
  /* en la Semana caben dos líneas: «Bowl de pechuga de pollo, garbanzo…» se quedaba en «Bowl de pechug…».
     Sin la coletilla («· más pechuga»), sin la lista tras la coma y sin «Extra de proteína:» */
  let x=String(t||'').replace(/^Extra de proteína:\s*/i,'+ ').replace(/^Extra:\s*/i,'+ ').split(' · ')[0].split(',')[0].replace(/\s*\(.*?\)\s*/g,' ').trim();
  return x.length>34?x.slice(0,33)+'…':x;}
function nomCorto(t){
  /* lo que cabe en una casilla de 45 px: el nombre sin lo que va entre paréntesis ni la coletilla */
  let x=String(t||'').replace(/\s*\(.*?\)\s*/g,' ').replace(/\s+(con|y|de la|del|al)\s.*$/i,'').trim();
  return x.length>18?x.slice(0,17)+'…':x;}
/* ---------- cuándo cocinar ---------- */
const COC_ORDEN=[6,0,1,2,3,4,5];   /* D L M X J V S: la semana de cocina empieza el domingo */
const COC_LET=['L','M','X','J','V','S','D'];
function diaDeTexto(t){
  const m=/\b(lun|mar|mi[eé]|jue|vie|s[aá]b|dom)/i.exec(String(t||''));if(!m)return 6;
  return {lun:0,mar:1,mie:2,'mié':2,jue:3,vie:4,sab:5,'sáb':5,dom:6}[m[1].toLowerCase()];}
function cocinarDatos(){
  const con=sbConsumo(),bs=store.batches.filter(function(b){return isBatch(b.id);});
  const ses=[],filas=[];
  bs.forEach(function(b,bi){
    const platos=store.dishes.filter(function(d){return d.batchId===b.id&&con[d.id];});
    if(!platos.length)return;
    const dia=diaDeTexto(b.when||b.label),col=COC_ORDEN.indexOf(dia);
    let rac=0;
    platos.forEach(function(d){
      const come=con[d.id],dias=[];
      Object.keys(come).forEach(function(w){const c=COC_ORDEN.indexOf(+w);
        const lleva=(c-col+7)%7;dias.push({col:c,q:Math.round(come[w]*10)/10,lleva:lleva});rac+=come[w];});
      dias.sort(function(a,b2){return ((a.col-col+7)%7)-((b2.col-col+7)%7);});
      filas.push({d:d,b:b,color:bi<3?('var(--ses'+(bi+1)+')'):'var(--ink2)',col:col,dias:dias});});
    ses.push({b:b,color:bi<3?('var(--ses'+(bi+1)+')'):'var(--ink2)',dia:dia,platos:platos,rac:Math.round(rac*10)/10});});
  const mal=[];filas.forEach(function(f){f.dias.forEach(function(x){if(x.lleva>4)mal.push({f:f,x:x});});});
  return {ses:ses,filas:filas,mal:mal,con:con};}
function renderCuandoCocinar(){
  const r=cocinarDatos();
  const tl=r.filas.length?('<div class="ctlh"><span></span>'+COC_ORDEN.map(function(w){return '<span>'+COC_LET[w]+'</span>';}).join('')+'</div>'+
    '<div class="ctl" role="table" aria-label="de la olla al plato">'+
    r.filas.map(function(f){
      const ult=f.dias.length?Math.max.apply(null,f.dias.map(function(x){return x.lleva;})):0;
      const celdas=COC_ORDEN.map(function(w,c){
        const off=(c-f.col+7)%7,come=f.dias.filter(function(x){return x.col===c;})[0];
        const en=off<=ult;
        const barra=en&&ult>0?('<span class="bar'+(off===0?' ini':'')+(off===ult?' fin':'')+'"></span>'):'';
        return '<span class="d"'+(en?'':' style="--c:transparent"')+'>'+barra+
          (off===0?'<span class="ck" title="se cocina">🔪</span>':'')+
          (come?('<span class="eat'+(come.lleva>4?' mal':'')+'" title="'+esc(f.d.name)+': '+fmt(come.q)+' ración(es) · lleva '+come.lleva+' día(s) en la nevera">'+fmt(come.q)+'</span>'):'')+'</span>';}).join('');
      return '<span class="n" title="'+esc(f.d.name)+'">'+esc((f.d.icon||'')+' '+nomCorto(f.d.name))+'</span>'+
        '<span class="fila" style="--c:'+f.color+'">'+celdas+'</span>';}).join('')+'</div>'):
    '<div class="empty">Nada de tanda esta semana: lo que comes se hace al momento.</div>';
  const m=r.mal[0];
  $('#main').innerHTML='<div class="grid">'+
    '<div class="subcab"><button class="btn s volver" data-a="types-vista" data-v="semana">'+gymIco('atras','gico sm')+' Semana base</button>'+
      '<h2 class="subtit">Cuándo cocinar</h2></div>'+
    '<div class="card">'+(r.ses.length?r.ses.map(function(s){
      return '<div class="cses"><span class="sq" style="background:'+s.color+'">🔪</span><span class="t"><b>'+esc(s.b.label)+(s.b.when?(' · '+esc(s.b.when)):'')+'</b>'+
        '<span>'+esc(s.platos.map(function(d){return nomCorto(d.name)+' ×'+fmt(Math.round(Object.keys(r.con[d.id]||{}).reduce(function(a,w){return a+r.con[d.id][w];},0)*10)/10);}).join(' · '))+
        ' · '+fmt(s.rac)+' táper'+(s.rac===1?'':'es')+'</span></span></div>';}).join(''):'<div class="empty">Ninguna sesión de cocina esta semana.</div>')+'</div>'+
    '<div class="card"><h3 style="margin:0 0 6px">De la olla al plato</h3>'+tl+
      (r.filas.length?'<div class="sbley"><span>🔪 se cocina</span><span><i class="o"></i>se come (raciones)</span><span style="color:var(--bad)">● más de 4 días en la nevera</span></div>':'')+
      (m?('<div class="caviso">«'+esc(m.f.d.name)+'» del '+SB_DIAS_L[COC_ORDEN[m.x.col]]+' lleva <b>'+m.x.lleva+' días</b> en la nevera. '+
        '<b style="color:var(--brand)">Congela ese táper el '+SB_DIAS_L[m.f.b?diaDeTexto(m.f.b.when||m.f.b.label):6]+'</b> o muévelo a otra sesión.'+
        (r.mal.length>1?(' Y '+(r.mal.length-1)+' más igual.'):'')+'</div>'):'')+
    '</div></div>';}
/* ---------- elegir la comida de una toma (sustituye a la lista nativa) ---------- */
function buscaCasa(t){
  /* cada palabra de la búsqueda empieza alguna palabra del texto; la búsqueda se trocea una vez */
  const qt=t?buscaToks(t):[];
  return function(txt){if(!t)return true;const it=buscaToks(txt);
    return qt.every(function(w){return it.some(function(i){return i.indexOf(w)===0;});});};}
function elegirOpciones(q,f){
  const t=alimTxt(q||'').trim();
  const casa=buscaCasa(t);
  const meals=store.meals.map(function(m){
    const names=(m.items||[]).map(function(it){const d=dishById(it.id);return d?d.name:'';}).filter(Boolean);
    return {tipo:'meal',id:m.id,n:m.name,e:'🍱',sub:names.join(' + '),t:totals(m.items||[]),cls:mealCls(m)};})
    .filter(function(x){return (f==='todo'||x.cls===f)&&casa(x.n+' '+x.sub);});
  const por=platosDeClase();
  const platos=store.dishes.map(function(d){return {tipo:'dish',id:d.id,n:d.name,e:d.icon||'🍽',
      sub:(isBatch(d.batchId)?((batchById(d.batchId)||{}).label||''):'al momento')+' · '+rac(d.portions),
      t:{kcal:+d.kcal||0,prot:+d.prot||0},usa:(por[f]||{})[d.id]||0};})
    .filter(function(x){return casa(x.n);})
    .sort(function(a,b){return b.usa-a.usa;});
  return {meals:f==='platos'?[]:meals,platos:(f==='platos'||t)?platos:[]};}
