  let x;
  if(tipo==='si'){const de=sal?Math.max(30,Math.round((mins(sal.sale)/60+24+trayectoMin()/60)*4)/4):39;x=[de,Math.min(42,de+(sal?c.siesta/60:1)),0];}
  else if(tipo==='gu')x=ult?[Math.min(41,ult[1]+1),Math.min(42,ult[1]+2),1]:[26,28,1];
