  const x={h:min(s.noche),rt:min(s.rt),guardia:gu,ratos:s.rt>0,siesta:min(s.siesta),kss:T.kss||0,
    tramos:T.tr.map(function(q){return [q[0],q[1],q[2]?1:0];}),mal:!!hueco,dde:hueco?hm(hueco[0]*60):'',da:hueco?hm(hueco[1]*60):''};
