  const casa=dp.map(function(x){const a=despAlim(x);return a?{x:x,a:a,w:frRz(x.nom+' '+a.n)}:null;}).filter(Boolean);
  /* lo que no se parte por su «con»/«y»: «café con leche», «arroz con pollo», tus platos */
  const comp=[],compFuera=[];
