function informeSesion(sid){
  /* EL INFORME AL TERMINAR: qué has hecho, cómo ha ido frente a la vez anterior y qué récords hay */
  const g=gymS(),ses=g.sesiones.filter(function(s){return s.id===sid;})[0];
  if(!ses)return null;
  const rt=rutinaPorId(ses.rutinaId);
  const series=seriesDeSesion(sid);
  const vol=Math.round(volDe(series));
  /* los récords: se comparan contra todo lo anterior A ESTA sesión */
  const previos={};
  /* …de verdad ANTERIOR: al abrir una sesión vieja contaba también las de después y sus récords
     salían a 0 */
  const fS=ses.fecha||'',tS=+ses.inicio||0;
  g.registro.forEach(function(x){
    if(x.sesionId===sid)return;
    if(fS&&(x.fecha>fS||(x.fecha===fS&&tS&&(+x.ts||0)>tS)))return;
    const rm=rmSerie(x);
    if(!previos[x.ex]||rm>previos[x.ex])previos[x.ex]=rm;});
  const records=[];
  const mejorPorEx={};
  series.forEach(function(x){
    const rm=rmSerie(x);
    if(!mejorPorEx[x.ex]||rm>mejorPorEx[x.ex].rm)mejorPorEx[x.ex]={rm:rm,kg:x.kg,reps:x.reps};});
  Object.keys(mejorPorEx).forEach(function(ex){
    if(mejorPorEx[ex].rm>(previos[ex]||0))records.push({ex:ex,kg:mejorPorEx[ex].kg,reps:mejorPorEx[ex].reps});});
  /* la vez anterior con la misma rutina */
  const antes=g.sesiones.filter(function(s){return s.rutinaId===ses.rutinaId&&s.id!==sid&&(!fS||(s.fecha||'')<=fS)&&(+s.inicio||0)<=(tS||Infinity);})
    .sort(function(a,b){return (b.fecha||'').localeCompare(a.fecha||'');})[0];
  let volAntes=null;
  if(antes){const sa2=seriesDeSesion(antes.id);
    volAntes=Math.round(volDe(sa2));}
  const regs=new Set();
  series.forEach(function(x){regionesDeEjercicio(x).forEach(function(r){regs.add(r);});});
  return {ses:ses,rt:rt,series:series,vol:vol,records:records,antes:antes,volAntes:volAntes,regs:regs,
    esfuerzo:series.filter(function(x){return +x.rpe>=9;}).length};}
function proximaVezHTML(inf){
  /* LA PRÓXIMA VEZ: el peso que toca en cada ejercicio con lo que acabas de hacer, y lo que toca
     ahora (comer y dormir). Así el resumen no es solo un trofeo: te deja la siguiente preparada */
  const exs={};inf.series.forEach(function(x){if(x.t!=='c'&&+x.kg>0)exs[x.ex]=(exs[x.ex]||0)+1;});
  const filas=Object.keys(exs).map(function(ex){
    const ej=(inf.rt&&inf.rt.ejercicios.filter(function(e){return e.ex===ex;})[0])||{reps:8};
    const pr=progresionDe(ex,exs[ex],ejRango(ej)[1],'9999-12-31');
    const col=pr.cl==='sube'?'var(--ok)':(pr.cl==='baja'?'var(--warn)':'var(--ink2)');
    return '<div class="gpr"><b>'+esc(ex)+'</b><span style="color:'+col+';font-weight:800">'+
      (pr.cl==='sube'?'▲ ':pr.cl==='baja'?'▼ ':'= ')+fmtKg(pr.kg)+' kg</span></div>';}).join('');
  const k=inf.ses.fecha,cc=comidasCfg();let sl=null;try{sl=sleepOf(iso(addDays(parseDate(k),1)));}catch(e){}
  const ahora='🍽 comida de después '+cc.conEntreno.de+' (≈0,4 g de proteína por kg)'+(sl&&sl.bed?(' · 🌙 a la cama '+sl.bed+' para tus horas'):'');
  return (filas?('<div class="card"><h2>La próxima vez</h2>'+filas+'</div>'):'')+
    '<div class="card"><div class="mini">'+esc(ahora)+'</div></div>';}
