/* ===================== ENTRENO: LA CIENCIA POR DEBAJO =====================
   Todo lo que la app calcula sin que tengas que tocar nada. Cada número sale de algo publicado:
     · rango de reps + RIR → doble progresión (subes cuando haces el tope de reps en todas las
       series sin llegar al fallo; Helms/Zourdos, RIR como autorregulación).
     · series por músculo y semana → ≥10 series duras/semana maximizan hipertrofia en la mayoría
       (Schoenfeld 2017, Pelland 2024); por debajo de ~8 poco estímulo, por encima de ~22 cuesta
       recuperar (puntos MEV/MRV de Israetel, orientativos).
     · descarga cada N semanas → bloques con una semana suave para disipar fatiga.
     · «listo» del día → sueño de verdad (Knowles 2018: dormir poco baja la fuerza máxima y la
       percepción de esfuerzo sube), guardia reciente y músculos entrenados hace <48 h.
     · e1RM → Epley, contando las reps que te dejaste (RIR). */
const MUSC_DEF={mev:8,min:10,max:20,mrv:22};
function muscV(k){const m=(store&&store.gym&&store.gym.musc)||{},v=+m[k];return (v>=1&&v<=40)?v:MUSC_DEF[k];}
const MUSC_OBJ={get mev(){return muscV('mev');},get min(){return muscV('min');},get max(){return muscV('max');},get mrv(){return muscV('mrv');}};
const MUSC_SUG={pecho:'press inclinado con mancuernas',espalda:'remo con mancuerna',hombros:'elevaciones laterales',
  biceps:'curl martillo',triceps:'extensión de tríceps en polea',cuadriceps:'sentadilla búlgara',isquiotibiales:'curl femoral',
  gluteos:'hip thrust',gemelos:'gemelos de pie',core:'plancha'};
function e1rm(kg,reps,rir){const r=(+reps||0)+(rir!=null&&+rir>0?+rir:0);return (+kg||0)*(1+r/30);}
/* el 1RM estimado de UNA serie, redondeado a 0,1: marcas, récords, objetivos y la curva usan este */
function rmSerie(x){return Math.round(e1rm(cargaSerie(x),x&&x.reps,x&&x.rir)*10)/10;}
function ejRango(ej){const lo=Math.max(1,+(ej&&ej.reps)||8),hi=Math.max(lo,+(ej&&ej.rmax)||lo);return [lo,hi];}
function ejRir(ej){const n=+(ej&&ej.rir);if(n>=0&&n<=5&&ej&&ej.rir!==''&&ej.rir!=null)return n;const d=+((store&&store.gym&&store.gym.rirDef));return (d>=0&&d<=5&&store.gym.rirDef!=null)?d:2;}
/* ---- bloques y descarga ---- */
/* ===================== LA VUELTA TRAS UN PARÓN =====================
   «Si llevo 2 meses sin entrenar no puedo hacer mi rutina: que la app me diga cuánto bajar y me suba poco a
   poco hasta volver». Antes, tras dos meses parado, la portada decía «Listo al 100 %» y el press banca
   «Sube a 85 kg» (de 82,5 hace dos meses). Con 2 semanas o más sin entrenar sale un plan de vuelta: empieza
   al 70 % del peso de antes, con 2 series y 4 repeticiones en la recámara, y sube cada semana hasta el 100 %
   en la mitad del tiempo parado (de 2 a 6 semanas). La semana no avanza hasta hacer sus entrenos.
   La ciencia: hasta ~3 semanas apenas se pierde fuerza; de 4 a 12, un 5–15 % (Mujika y Padilla 2000;
   McMaster 2013), y volver de golpe es cuando más lesiones hay (Gabbett 2016). design/entreno-vuelta.
   Se guarda en gym.regreso (gym.vuelta son los minutos de volver a casa). */
const REGRESO_DIAS=14;
function repsTxt(n){return n+(n===1?' repetición':' repeticiones');}
/* plan nuevo: arranca en `ini` % y sube 10 puntos por semana hasta el 100 (35·45·…·95·100). `vi`/`mas` son la
   fórmula vieja (lineal desde 60/70/75): la siguen usando los planes guardados sin `ini`, para no cambiarles las cifras */
const REGRESO_RITMO={suave:{ini:30,vi:60,mas:2,txt:'más suave'},normal:{ini:35,vi:70,mas:0,txt:'normal'},rapido:{ini:40,vi:75,mas:-1,txt:'más rápido'}};
function regresoPct(v,i,N){
  /* el % de peso de la semana i: sube por pasos si el plan trae `ini`; si no, la fórmula lineal de antes */
  if(+v.ini>0)return Math.min(100,Math.round(+v.ini+(+v.paso||10)*(i-1)));
  const r=REGRESO_RITMO[v.ritmo]||REGRESO_RITMO.normal,t=N>1?(i-1)/(N-1):1;
  return Math.round((r.vi+(100-r.vi)*t)/5)*5;}
function regresoCon(v,k){
  /* ese plan con otro ritmo (sin guardarlo): el `ini` del plan nuevo cambia con el ritmo, el del viejo no existe */
  const o=Object.assign({},v,{ritmo:k});if(+v.ini>0)o.ini=REGRESO_RITMO[k].ini;return o;}
function diasEntreK(a,b){const x=parseDate(a),y=parseDate(b);return x&&y?Math.round((y-x)/864e5):0;}
function ultimoEntreno(antes){
  /* el último día con una serie apuntada antes de esa fecha */
  let u='';gymS().registro.forEach(function(x){if(x.fecha&&x.fecha<antes&&x.fecha>u)u=x.fecha;});return u;}
function regresoS(){
  /* el plan de vuelta en marcha (o null). Se crea solo al pasar REGRESO_DIAS sin entrenar con historial
     detrás, y se rehace si vuelves a parar otras dos semanas en mitad del plan */
  const g=gymS(),hoy=iso(new Date()),ult=ultimoEntreno(hoy);
  if(!ult)return null;
  let v=g.regreso&&typeof g.regreso==='object'?g.regreso:null;
  const parado=diasEntreK(ult,hoy);
  if(parado>=REGRESO_DIAS&&(!v||ult>=v.desde))
    {const rit=(v&&REGRESO_RITMO[v.ritmo])?v.ritmo:'normal';
      v=g.regreso={desde:hoy,ultimo:ult,parado:parado,ritmo:rit,ini:REGRESO_RITMO[rit].ini,paso:10};}
  /* un plan en curso de antes del sistema nuevo (sin `ini`: empezaba al 70 %, dos semanas) se rehace UNA vez con el sistema nuevo
     (ini según su ritmo, +10 por semana). Conserva ultimo, parado y ritmo; el registro de entrenos no se toca */
  if(v&&!v.fin&&!(+v.ini>0)){
    const rit=REGRESO_RITMO[v.ritmo]?v.ritmo:'normal';
    const lun=iso(mondayOf(new Date()));   /* desde el lunes (o desde que empezó, si fue después): así cuentan los entrenos de esta semana */
    v=g.regreso=Object.assign({},v,{desde:(v.desde&&v.desde>lun?v.desde:lun),ritmo:rit,ini:REGRESO_RITMO[rit].ini,paso:10});save();}
  return v&&!v.fin?v:null;}
function regresoSemanas(v){
  if(+v.ini>0)return 1+Math.max(1,Math.ceil((100-v.ini)/(+v.paso||10)));   /* semanas hasta llegar al 100 */
  const r=REGRESO_RITMO[v.ritmo]||REGRESO_RITMO.normal,w=Math.floor((+v.parado||REGRESO_DIAS)/7);
  return Math.max(2,Math.min(8,Math.max(2,Math.min(6,Math.round(w/2)))+r.mas));}
function regresoDiasSem(i){return i===1?2:Math.max(2,Math.min(4,+gymS().minSemana||3));}
function regresoDe(key){
  /* en qué semana del plan cae ese día: cuenta los días entrenados desde que empezó (antes de ese día) */
  const v=regresoS();if(!v||!key||key<v.desde)return null;
  const N=regresoSemanas(v),f={};
  gymS().registro.forEach(function(x){if(x.fecha&&x.fecha>=v.desde&&x.fecha<key)f[x.fecha]=1;});
  const hechos=Object.keys(f).length;
  let acc=0,i=1;
  for(;i<=N;i++){const d=regresoDiasSem(i);if(hechos<acc+d)break;acc+=d;}
  if(i>N){if(key===iso(new Date())){v.fin=key;}return null;}
  const t=N>1?(i-1)/(N-1):1;
  let pct=regresoPct(v,i,N);
  /* si la última sesión del plan fue «dura», esta semana se queda un 5 % más abajo */
  const ses=gymS().sesiones.filter(function(x){return x.fecha>=v.desde&&x.fecha<key;}).sort(function(a,b){return a.fecha<b.fecha?1:-1;})[0];
  const duro=i>1&&ses&&+ses.rpe>=8;if(duro)pct-=5;
  return {sem:i,de:N,pct:pct,rir:Math.round(4-3*t),dias:regresoDiasSem(i),hechos:hechos-acc,duro:duro,
    semanasParado:Math.floor((+v.parado||0)/7),ultimo:v.ultimo,desde:v.desde,ritmo:v.ritmo,
    series:function(full){return Math.max(1,Math.min(full,Math.round(2+(full-2)*t)));}};}
function regresoRef(nombre,desde){
  /* lo que movías antes de parar: el peso de trabajo más alto del último día de ese ejercicio antes del plan */
  const d=diasDeEjercicio(nombre).filter(function(f){return f<desde;})[0];if(!d)return null;
  const l=seriesDeDia(nombre,d).filter(function(x){return x.t!=='c';});
  return {kg:l.reduce(function(a,x){return Math.max(a,+x.kg||0);},0),reps:l.reduce(function(a,x){return Math.max(a,+x.reps||0);},0),n:l.length,dia:d};}
function diaMesTxt(key){const d=parseDate(key);return d?d.getDate()+' '+MON[d.getMonth()]:String(key||'');}
function renderGymPeso(){
  /* «Tu objetivo de peso»: meta, ritmo, lo que sale (kcal, proteína, fecha) y la gráfica del peso. Todo en el móvil. */
  const p=perfilS(),o=p.objetivo||{},ob=objetivoPeso(),ps=p.pesos.slice(-60);
  const TOPE={imc:'tu meta quedaba por debajo de un IMC de 18,5: la he subido',ritmo:'el ritmo pasaba del 1 % de tu peso por semana: lo he bajado',
    deficit:'el déficit pasaba del 25 % de lo que gastas: lo he recortado',basal:'las kcal bajaban de tu metabolismo basal o de 1.500: me quedo ahí'};
  let svg='';
  if(ps.length>=2){const W=300,H=90,v=ps.map(function(x){return x.kg;}).concat(ob?[ob.meta]:[]),lo=Math.min.apply(null,v)-1,hi=Math.max.apply(null,v)+1,
      px=function(i){return Math.round(i/(ps.length-1)*W);},py=function(k){return Math.round(H-6-(k-lo)/(hi-lo)*(H-12));};
    svg='<svg class="gline" viewBox="0 0 '+W+' '+H+'" preserveAspectRatio="none" role="img" aria-label="Tu peso apuntado">'+
      (ob?'<line x1="0" x2="'+W+'" y1="'+py(ob.meta)+'" y2="'+py(ob.meta)+'" stroke="var(--ok)" stroke-dasharray="4 4"></line>':'')+
      '<polyline fill="none" stroke="var(--brand)" stroke-width="3" stroke-linejoin="round" points="'+ps.map(function(x,i){return px(i)+','+py(x.kg);}).join(' ')+'"></polyline></svg>';}
  const sin=!gastoDiario();
  $('#main').innerHTML='<div class="grid">'+gymSubcab('Tu objetivo de peso')+
    '<div class="card"><div class="cap gvcap">TU META</div>'+
      (sin?'<p class="mini">Para calcularlo faltan tu peso, altura, edad y sexo (Ajustes → perfil).</p>':'')+
      '<label class="fld">peso de meta (kg)<input type="number" inputmode="decimal" min="30" max="300" step="0.5" value="'+(+o.kg>0?o.kg:'')+'" data-a="obj-kg"></label>'+
      '<div class="cap gvcap" style="margin-top:10px">RITMO (kg por semana)</div><div class="chips gpesorit">'+OBJ_RITMOS.map(function(r){
        return '<button class="chipx'+((+o.ritmo||0.5)===r?' on':'')+'" data-a="obj-ritmo" data-v="'+r+'">'+fmtC(r)+'</button>';}).join('')+'</div></div>'+
    (ob&&ob.perder?'<div class="card"><div class="cap gvcap">TU CUENTA</div><div class="big">'+ob.kcal+' kcal al día</div>'+
      '<p class="mini">Proteína: <b>'+ob.prot+' g</b> al día · de '+fmtKg(ob.partida)+' a '+fmtKg(ob.meta)+' kg a '+fmtC(ob.ritmo)+' kg por semana: <b>'+ob.semanas+' semanas</b>, hacia el '+esc(fechaCortaTxt(ob.fecha))+' de '+esc(MON[(parseDate(ob.fecha)||new Date()).getMonth()])+'.</p>'+
      (ob.topes.length?'<p class="mini" style="color:var(--warn,var(--ink2))">'+ob.topes.map(function(t){return esc(TOPE[t]);}).join('. ')+'.</p>':'')+
      (p.meta!=='perder'?'<button class="btn s" data-a="obj-usar">usar estas kcal (poner mi meta en «perder»)</button>':'<p class="mini">Estas son ya tus kcal de Comer.</p>')+'</div>':
     (ob?'<div class="card"><p class="mini">Tu meta no está por debajo de tu peso de ahora ('+fmtKg(ob.partida)+' kg): no hay déficit que calcular.</p></div>':''))+
    '<div class="card"><div class="cap gvcap">TU PESO</div>'+(svg||'<p class="mini">Apunta tu peso un par de días y sale la gráfica.</p>')+
      /* la gráfica se estira al ancho y sus textos saldrían deformados: las cifras van debajo, en texto */
      (svg?'<p class="mini gpesoeje"><span>'+esc(diaMesTxt(ps[0].k))+' · <b>'+fmtKg(ps[0].kg)+' kg</b></span><span>'+esc(diaMesTxt(ps[ps.length-1].k))+' · <b>'+fmtKg(ps[ps.length-1].kg)+' kg</b></span></p>'+
        (ob?'<p class="mini">La línea verde a rayas es tu meta: <b>'+fmtKg(ob.meta)+' kg</b>.</p>':''):'')+
      '<p class="mini">Partes de '+(pesoPartida()?fmtKg(pesoPartida())+' kg (media de tus últimos 7 días apuntados)':'—')+'.</p></div>'+
    '<div class="card"><p class="mini">Si has tenido problemas con la comida, habla antes con tu médico/a. Estos números son una guía, no una dieta. Todo se queda en tu móvil.</p>'+
      (+o.kg>0?'<button class="btn s" data-a="obj-quitar">quitar el objetivo</button>':'')+'</div></div>';}
function renderGymRegreso(){
  const vu=regresoDe(iso(new Date()));
  if(!vu){ui.gymPanel='';return renderGymPortada();}
  const v0=regresoS(),filas=[];
  for(let i=1;i<=vu.de;i++){const t=vu.de>1?(i-1)/(vu.de-1):1,pct=i===vu.sem?vu.pct:regresoPct(v0,i,vu.de);
    filas.push('<tr class="'+(i===vu.sem?'on':'')+'"><td><b>'+i+'</b>'+(i===vu.sem?' · ahora':'')+'</td><td>'+regresoDiasSem(i)+'</td><td>'+(i===vu.de?'tus series':(i===1?'2':'2–3'))+
      '</td><td><b>'+pct+' %</b></td><td>'+Math.round(4-3*t)+'</td></tr>');}
  const refs=[];gymS().rutinas.forEach(function(rt){rt.ejercicios.forEach(function(e){const x=regresoRef(e.ex,vu.desde);if(x&&x.kg>0&&refs.length<3)refs.push(e.ex.toLowerCase()+' '+fmtKg(x.kg)+' kg');});});
  $('#main').innerHTML='<div class="grid">'+gymSubcab('Tu plan de vuelta')+
    '<div class="card"><div class="cap gvcap">'+(vu.semanasParado>=2?vu.semanasParado+' SEMANAS':diasEntreK(vu.ultimo,vu.desde)+' DÍAS')+' PARADO → '+vu.de+' SEMANAS DE VUELTA</div>'+
      '<table class="gvtab"><tr><th>Semana</th><th>Días</th><th>Series</th><th>Peso</th><th>Te sobran</th></tr>'+filas.join('')+'</table>'+
      '<p class="mini">Esta semana: <b>'+vu.dias+' días</b> · '+(vu.sem===vu.de?'tus series':'2'+(vu.sem>1?'–3':'')+' series por ejercicio')+' · el '+vu.pct+' % de tu peso · que te sobren '+repsTxt(vu.rir)+(vu.duro?' · un 5 % menos porque la última fue dura':'')+'. Llevas <b>'+vu.hechos+' de '+vu.dias+'</b> entrenos de esta semana.</p>'+
      '<p class="mini">El 100 % es lo que movías antes de parar'+(refs.length?' ('+esc(refs.join(', '))+'…)':'')+'. Después vuelve tu progresión de siempre.</p></div>'+
    '<div class="card"><div class="cap gvcap">EL RITMO</div><div class="chips">'+['suave','normal','rapido'].map(function(k){
      const v2=regresoCon(regresoS(),k);
      return '<button class="chipx'+(vu.ritmo===k?' on':'')+'" data-a="regreso-ritmo" data-v="'+k+'">'+REGRESO_RITMO[k].txt+' · '+regresoSemanas(v2)+' sem</button>';}).join('')+'</div>'+
      '<p class="mini">Elige «más suave» si estás de guardias seguidas o durmiendo poco.</p></div>'+
    '<div class="card"><div class="cap gvcap">EN QUÉ SE BASA</div><ul class="gvcien">'+
      '<li>Hasta ~3 semanas parado apenas se pierde fuerza; de 4 a 12 se pierde un 5–15 %, y más el aguante que la fuerza.</li>'+
      '<li>Volver de golpe al peso y al volumen de antes es cuando más agujetas fuertes y lesiones hay: la carga tiene que subir poco a poco.</li>'+
      '<li>La fuerza vuelve mucho antes de lo que costó ganarla («memoria muscular»): en unas semanas estás donde lo dejaste.</li></ul></div>'+
    '<div class="card"><div class="cap gvcap">SI TE SALTAS DÍAS</div><p class="mini">La semana no avanza hasta que haces sus entrenos. Si vuelves a parar más de 2 semanas, el plan se rehace desde donde estés. Si al terminar una sesión dices que fue dura, la semana siguiente va un 5 % más abajo.</p>'+
      '<button class="btn s" data-a="regreso-quitar">no lo necesito: quitar el plan</button></div>'+
  '</div>';}
function descargaCada(){const n=+gymS().descargaCada;return (n>=3&&n<=12)?Math.round(n):5;}
function bloqueDesde(){
  /* el primer bloque empieza el lunes en que llega esta función, no el día de tu primer registro:
     si no, a alguien con meses de historial le caería una descarga por sorpresa */
  const g=gymS();if(g.bloqueDesde&&parseDate(g.bloqueDesde))return g.bloqueDesde;
  g.bloqueDesde=iso(mondayOf(new Date()));
  return g.bloqueDesde;}
function bloqueDe(key){
  /* semana n de N del bloque; la última es de descarga */
  const d=parseDate(key)||new Date(),c=descargaCada();
  const w=Math.floor((mondayOf(d)-mondayOf(parseDate(bloqueDesde())))/(7*86400000));
  const n=((w%c)+c)%c+1;
  return {sem:n,de:c,descarga:n===c&&w>=c-1,bloque:Math.floor(Math.max(0,w)/c)+1};}
/* ---- listo para entrenar ---- */
function suenoNoche(key){
  const r=suenoReal(key);if(r)return {h:suenoTotal(r),real:true};
  let sl=null;try{sl=sleepOf(key);}catch(e){}
  return {h:sl&&sl.h!=null?sl.h:null,real:false};}
let _listoTick=-1,_listoMemo={};
function listoDe(key){
  if(_listoTick!==_renderTick){_listoMemo={};_listoTick=_renderTick;}
  return _listoMemo[key]||(_listoMemo[key]=listoDe0(key));}
function listoDe0(key){
  /* 100 = llegas bien. Resta por dormir menos de tu objetivo, por salir de guardia, por guardia
     hace dos días, por músculos de la rutina tocados hace <48 h y por subir la carga de golpe */
  const c=suenoCfg(),s=suenoNoche(key),motivos=[];let v=100;
  if(s.h!=null&&s.h<c.min){const q=Math.round((c.min-s.h)*9)+(s.h<5?10:0);   /* por debajo de 5 h la caída de fuerza se acelera */v-=q;motivos.push('dormiste '+fmtHM(s.h*60)+(s.real?'':' (según el plan)'));}
  /* la deuda acumulada pesa aparte de la última noche: diez horas perdidas en dos semanas se notan
     aunque anoche durmieras bien */
  const st=suenoEstado(key);
  if(st.nivel===3){v-=15;motivos.push('3 noches con '+String(st.suma).replace('.',',')+' h');}
  else if(st.nivel===2&&st.fase.id!=='saliente'){v-=10;motivos.push('3 noches con '+String(st.suma).replace('.',',')+' h');}
  const d=parseDate(key);
  if(salidaDeGuardia(key)){v-=20;motivos.push('sales de guardia');}
  else if(d&&salidaDeGuardia(iso(addDays(d,-1)))){v-=8;motivos.push('guardia hace dos días');}
  const e=entrenoDe(key),rt=e&&e.rutina?e.rutina:rutinaDeFecha(key);
  if(rt){const regs=regionesDeRutina(rt.id),ult=gymDescanso();
    const cansados=ult.filter(function(x){return regs.has(x.reg)&&x.dias!=null&&x.dias<2;}).map(function(x){return MREG_LABEL[x.reg]||x.reg;});
    if(cansados.length){v-=10;motivos.push(cansados.join(' y ').toLowerCase()+' aún cargad'+(cansados.length>1?'os':'o'));}}
  const a=acwrDe(key);
  if(a&&a.r>1.5){v-=10;motivos.push('la carga sube de golpe');}else if(a&&a.r>1.3){v-=5;}
  const vu=regresoDe(key);
  if(vu){v-=vu.sem===1?25:(vu.sem===2?15:5);motivos.push('vuelves de '+(vu.semanasParado>=2?vu.semanasParado+' semanas':'2 semanas')+' parado');}
  v=Math.max(20,Math.min(100,Math.round(v)));
  const rec=vu?'vuelta':(v>=80?'normal':(v>=60?'ajusta':'corta'));
  return {v:v,motivos:motivos,rec:rec,hayDatos:s.h!=null,
    txt:rec==='vuelta'?'Hoy versión de vuelta, no tu sesión de siempre.':rec==='normal'?'Entrena normal.':(rec==='ajusta'?'Quita una serie a los básicos o baja un 5 %.':'Hoy, versión corta: mitad de series y −10 % de peso.')};}
function listoHTML(key){
  const l=listoDe(key);if(!l.hayDatos&&!l.motivos.length)return '';
  const col=l.v>=80?'var(--ok)':(l.v>=60?'var(--warn)':'var(--bad)');
  return '<div class="glisto" style="--c:'+col+'"><div class="g" style="background:conic-gradient(var(--c) 0 '+l.v+'%,var(--line) '+l.v+'% 100%)"><b>'+l.v+'</b></div>'+
    '<div class="t"><b>Listo al '+l.v+' %</b>'+esc(l.motivos.length?l.motivos.join(' · ')+'. ':'')+'<b class="r">'+esc(l.txt)+'</b></div></div>';}
/* ---- carga (sRPE) y ACWR ---- */
/* la carga de cada día, sacada una vez por pintado (el ACWR pide 28 días y se pinta varias veces) */
let _cargaTick=-1,_cargaMapa=null,_cargaPrimera='';
function cargaMapa(){
  if(_cargaMapa&&_cargaTick===_renderTick)return _cargaMapa;
  const g=gymS(),m={};_cargaPrimera='';
  g.sesiones.forEach(function(s){m[s.fecha]=(m[s.fecha]||0)+((+s.carga>0)?+s.carga:((+s.duracionMin||0)*5));   /* sin esfuerzo apuntado, «dura» (5) por defecto */
    if(s.fecha&&(!_cargaPrimera||s.fecha<_cargaPrimera))_cargaPrimera=s.fecha;});
  g.cardio.forEach(function(x){m[x.fecha]=(m[x.fecha]||0)+(+x.duracionMin||0)*4;});
  _cargaMapa=m;_cargaTick=_renderTick;return m;}
function cargaDia(key){return cargaMapa()[key]||0;}
function cargaSemana(lunKey){let c=0;const l=parseDate(lunKey);for(let i=0;i<7;i++)c+=cargaDia(iso(addDays(l,i)));return c;}
function acwrDe(key){
  /* carga de los últimos 7 días frente a la media semanal de los últimos 28 (Gabbett 2016). Sin
     un mes de datos no significa nada, así que no se da */
  const d=parseDate(key);if(!d)return null;
  let ag=0,cr=0;for(let i=0;i<28;i++){const c=cargaDia(iso(addDays(d,-i)));if(i<7)ag+=c;cr+=c;}
  cargaMapa();const primera=_cargaPrimera;
  if(!primera||(d-parseDate(primera))<21*86400000||!cr)return null;
  return {r:Math.round(ag/(cr/4)*100)/100,aguda:ag,cronica:Math.round(cr/4)};}
/* ---- series por músculo ---- */
function seriesMusculo(lunKey){
  const l=parseDate(lunKey),ks={};for(let i=0;i<7;i++)ks[iso(addDays(l,i))]=1;
  const out={};MREGIONES.forEach(function(r){out[r]=0;});
  /* el músculo principal cuenta la serie entera y los que ayudan, media (como se cuenta en la
     literatura de volumen): antes 3 series de press banca eran también 3 de tríceps y 3 de hombro */
  gymS().registro.forEach(function(x){if(!ks[x.fecha]||x.t==='c')return;
    Array.from(regionesDeEjercicio(x)).forEach(function(r,i){out[r]=(out[r]||0)+(i===0?1:0.5);});});
  Object.keys(out).forEach(function(r){out[r]=Math.round(out[r]*2)/2;});
  return out;}
function seriesPrevistas(lunKey){
  /* lo que el plan aún tiene para esta semana (de mañana al domingo), por músculo: el viernes «pecho 3,
     por debajo de 8» saltaba aunque el sábado tocara otra vez fuerza */
  const out={},hoyK=iso(new Date());MREGIONES.forEach(function(r){out[r]=0;});
  for(let i=0;i<7;i++){const k=iso(addDays(parseDate(lunKey),i));if(k<=hoyK)continue;
    const e=entrenoDe(k),rt=e&&e.tipo==='fuerza'?e.rutina:null;if(!rt)continue;
    rt.ejercicios.forEach(function(ej){const n=ejSets(ej).filter(function(z){return z.t!=='c';}).length;
      Array.from(regionesDeEjercicio({ex:ej.ex})).forEach(function(r,j){out[r]=(out[r]||0)+(j===0?n:n/2);});});}
  return out;}
function musculosHTML(sel){
  const lun=iso(mondayOf(parseDate(sel)||new Date())),sm=seriesMusculo(lun),pv=seriesPrevistas(lun);
  const regs=MREGIONES.filter(function(r){return sm[r]>0;});
  if(!regs.length)return '';
  const mx=30,tot=function(r){return (sm[r]||0)+(pv[r]||0);};
  const altos=regs.filter(function(r){return sm[r]>MUSC_OBJ.mrv;});
  /* el aviso cuenta lo hecho más lo que el plan aún tiene: solo salta si ni así llegas */
  const faltan=MREGIONES.filter(function(r){return ['pecho','espalda','hombros','cuadriceps','isquiotibiales'].indexOf(r)>=0&&tot(r)<MUSC_OBJ.mev;});
  return '<div class="card gmus"><div class="row"><b>Series por músculo · esta semana</b><span class="sp"></span><span class="mini">objetivo '+MUSC_OBJ.min+'–'+MUSC_OBJ.max+'</span></div>'+
    regs.sort(function(a,b){return sm[b]-sm[a];}).map(function(r){const n=sm[r];
      const cl=n>MUSC_OBJ.mrv?'hi':(n<MUSC_OBJ.mev?'lo':(n>=MUSC_OBJ.min&&n<=MUSC_OBJ.max?'ok':'mid'));
      return '<div class="r"><span>'+esc(MREG_LABEL[r]||r)+'</span><div class="tr"><u style="left:'+(MUSC_OBJ.min/mx*100)+'%;width:'+((MUSC_OBJ.max-MUSC_OBJ.min)/mx*100)+'%"></u>'+
        '<i class="'+cl+'" style="width:'+Math.min(100,n/mx*100)+'%"></i></div><b class="'+cl+'">'+fmtKg(n)+(pv[r]?'<small> +'+fmtKg(Math.round(pv[r]*2)/2)+'</small>':'')+'</b></div>';}).join('')+
    (MREGIONES.some(function(r){return pv[r]>0;})?'<div class="mini" style="margin-top:4px">+N: lo que el plan aún tiene esta semana.</div>':'')+
    (faltan.length?('<div class="mini" style="margin-top:6px">Por debajo de '+MUSC_OBJ.mev+': '+faltan.map(function(r){return '<b style="color:var(--ink)">'+esc((MREG_LABEL[r]||r).toLowerCase())+'</b> ('+esc(MUSC_SUG[r])+')';}).join(', ')+'. Añádelo al próximo día de fuerza.</div>'):'')+
    (altos.length?('<div class="mini" style="margin-top:4px;color:var(--bad)">Pasado de '+MUSC_OBJ.mrv+': '+altos.map(function(r){return esc((MREG_LABEL[r]||r).toLowerCase());}).join(', ')+'. Más series ya no suman y cuestan recuperar.</div>'):'')+
    '</div>';}
/* ---- progreso: e1RM por semana ---- */
function e1rmSemanas(ex,n){
  const hoy=mondayOf(new Date()),out=[];
  const xs=(gymIdx().byEx[ex]||[]).filter(function(x){return x.t!=='c'&&cargaSerie(x)>0;});
  for(let w=n-1;w>=0;w--){const l=addDays(hoy,-7*w),f=addDays(l,7);let best=0;
    xs.forEach(function(x){const d=parseDate(x.fecha);if(d>=l&&d<f){const v=e1rm(cargaSerie(x),x.reps,x.rir);if(v>best)best=v;}});
    let gu=0;for(let i=0;i<7;i++){const sh=shiftById(dayInfo(iso(addDays(l,i))).shiftId);if(sh&&isGuardia(sh))gu++;}
    out.push({l:iso(l),v:best?Math.round(best*10)/10:null,gu:gu});}
  return out;}
function progresoE1rmHTML(){
  const exs=Object.keys(gymIdx().byEx).filter(function(ex){return (gymIdx().byEx[ex]||[]).some(function(x){return cargaSerie(x)>0;});})
    .sort(function(a,b){return (gymIdx().byEx[b]||[]).length-(gymIdx().byEx[a]||[]).length;});
  if(!exs.length)return '';
  const sel=exs.indexOf(ui.progEx)>=0?ui.progEx:exs[0];
  const sem=e1rmSemanas(sel,12),vals=sem.filter(function(x){return x.v;}).map(function(x){return x.v;});
  const lo=vals.length?Math.min.apply(null,vals):0,hi=vals.length?Math.max.apply(null,vals):1,rg=Math.max(1,hi-lo);
  const W=300,H=110,px=function(i){return Math.round(i/(sem.length-1)*W);},py=function(v){return Math.round(H-8-(v-lo)/rg*(H-24));};
  const pts=sem.map(function(x,i){return x.v?(px(i)+','+py(x.v)):null;}).filter(Boolean).join(' ');
  const bandas=sem.map(function(x,i){return x.gu>=3?'<rect x="'+(px(i)-12)+'" y="0" width="24" height="'+H+'" fill="var(--bad)" opacity=".12"></rect>':'';}).join('');
  const primero=vals[0],ultimo=vals[vals.length-1],dif=(primero&&ultimo)?Math.round((ultimo-primero)/primero*100):null;
  const basicos=exs.slice(0,6).map(function(ex){const s=e1rmSemanas(ex,5).filter(function(x){return x.v;});
    if(!s.length)return '';const a=s[0].v,b=s[s.length-1].v,d=Math.round(b-a);
    return '<div class="gpr"><b>'+esc(ex)+'</b><span>1RM est. '+fmtKg(Math.round(b))+'</span><span style="color:'+(d>0?'var(--ok)':(d<0?'var(--bad)':'var(--ink2)'))+';font-weight:800">'+(d>0?'▲ ':d<0?'▼ ':'= ')+Math.abs(d)+'</span></div>';}).join('');
  const bq=bloqueDe(iso(new Date()));
  return '<div class="card"><div class="row"><b>1RM estimado</b><span class="sp"></span><span class="mini">12 semanas'+(dif!=null?(' · <b style="color:'+(dif>=0?'var(--ok)':'var(--bad)')+'">'+(dif>0?'+':'')+dif+' %</b>'):'')+'</span></div>'+
    '<div class="gchips">'+exs.slice(0,8).map(function(ex){return '<button class="'+(ex===sel?'on':'')+'" data-a="prog-ex" data-n="'+esc(ex)+'">'+esc(ex)+'</button>';}).join('')+'</div>'+
    /* con menos de tres semanas una curva de 12 es un gráfico vacío con dos puntos: hasta entonces, la lista */
    (vals.length>=3?('<svg class="gline" viewBox="0 0 '+W+' '+H+'" preserveAspectRatio="none" role="img" aria-label="1RM estimado de '+esc(sel)+' por semana">'+bandas+
      (pts?'<polyline fill="none" stroke="var(--brand)" stroke-width="3" stroke-linejoin="round" points="'+pts+'"></polyline>':'')+
      sem.map(function(x,i){return x.v?'<circle cx="'+px(i)+'" cy="'+py(x.v)+'" r="3.5" fill="var(--brand)"></circle>':'';}).join('')+'</svg>'+
    '<div class="gbarsx"><span>'+esc(fechaCortaTxt(sem[0].l))+'</span><span style="text-align:right">esta semana</span></div>'+
    '<p class="mini" style="margin:6px 0 0">Mejor serie de cada semana, contando las reps que te dejaste. Las franjas rojas son semanas de 3 guardias o más.</p>'):
      (basicos||'<p class="mini" style="margin:6px 0 0">Sin series con peso en 12 semanas.</p>')+(vals.length?'<p class="mini" style="margin:6px 0 0">Con tres semanas de datos sale la curva.</p>':''))+'</div>'+
    (basicos&&vals.length>=3?'<div class="card"><b>Tus básicos · últimas 5 semanas</b>'+basicos+'</div>':'')+
    '<div class="card"><div class="row"><b>Bloque '+bq.bloque+' · semana '+bq.sem+' de '+bq.de+'</b><span class="sp"></span>'+(bq.descarga?'<span class="tag b1">DESCARGA</span>':'')+'</div>'+
      '<p class="mini" style="margin:6px 0 0">'+(bq.descarga?'Esta semana es de descarga: la app te propone la mitad de series y un 10 % menos. Es cuando se nota lo entrenado.':
        ('Cada '+bq.de+' semanas, una de descarga (mitad de series, −10 %). La próxima empieza en '+(bq.de-bq.sem)+' semana'+(bq.de-bq.sem===1?'':'s')+'.'))+'</p>'+
      '<div class="row" style="margin-top:8px;gap:8px"><label class="mini">descarga cada <input inputmode="numeric" style="width:48px" value="'+bq.de+'" data-a="gym-descarga"> semanas</label>'+
        '<span class="sp"></span><button class="btn s" data-a="gym-bloque-hoy">empezar bloque hoy</button></div></div>';}
/* ===================== OBJETIVOS: minutos, agua y fecha límite ===================== */
function minutosSemana(lunKey){
  const l=parseDate(lunKey),ks={};for(let i=0;i<7;i++)ks[iso(addDays(l,i))]=1;const g=gymS();let m=0;
  g.sesiones.forEach(function(s){if(ks[s.fecha])m+=+s.duracionMin||0;});
  g.cardio.forEach(function(x){if(ks[x.fecha])m+=+x.duracionMin||0;});
  return m;}
function aguaMes(ym){
  /* metros de agua del mes: series de metros, cardio de natación y los Lloretazos (sin metros: se cuentan aparte) */
  const g=gymS();let m=0;
  g.registro.forEach(function(x){if(String(x.fecha||'').slice(0,7)===ym&&+x.m>0)m+=+x.m;});
  g.cardio.forEach(function(x){if(String(x.fecha||'').slice(0,7)===ym&&/nata|piscina|agua/i.test(x.tipo||''))m+=Math.round((+x.distanciaKm||0)*1000);});
  const ll=eventosS().filter(function(e){return e.lloret&&e.on!==false&&String(e.fecha||'').slice(0,7)===ym;}).length;
  return {m:m,lloret:ll};}
function semanasConstancia(meta,n){
  const out=[],lun=mondayOf(new Date());
  for(let w=n;w>=1;w--){const l=addDays(lun,-7*w);let d=0,gu=0;
    for(let i=0;i<7;i++){const k=iso(addDays(l,i));if(gymHechoEn(k))d++;const sh=shiftById(dayInfo(k).shiftId);if(sh&&isGuardia(sh))gu++;}
    out.push({l:iso(l),d:d,ok:d>=meta,gu:gu});}
  return out;}
function objetivoExtraHTML(o,e){
  if(o.tipo==='fuerza'&&o.fecha){
    const sem=Math.max(0.1,(parseDate(o.fecha)-new Date())/(7*86400000)),ritmo=e.ritmoSem!=null?e.ritmoSem:(e.av||0)/8,nec=Math.max(0,(e.falta||0))/sem;
    const eta=ritmo>0&&(e.falta||0)>0?addDays(new Date(),Math.ceil((e.falta||0)/ritmo*7)):null;
    const ok=(e.falta||0)<=0||ritmo>=nec;
    return '<div class="objvia"><span class="st '+(ok?'ok':'no')+'">'+(ok?'EN RITMO':'LENTO')+'</span><span>para el '+esc(fechaCortaTxt(o.fecha))+
      ': necesitas +'+fmtKg(Math.round(nec*10)/10)+' kg/sem · llevas '+(ritmo>=0?'+':'')+fmtKg(Math.round(ritmo*10)/10)+
      (eta?(' · a este ritmo, el '+esc(fechaCortaTxt(iso(eta)))):'')+'</span></div>';}
  if(o.tipo==='constancia'){
    const s=semanasConstancia(+o.meta||1,12),ok=s.filter(function(x){return x.ok;}).length,mal=s.filter(function(x){return !x.ok;});
    const porG=mal.filter(function(x){return x.gu>=2;}).length;
    return '<div class="objsem">'+s.map(function(x){return '<i class="'+(x.ok?'on':'')+'" title="'+esc(fechaCortaTxt(x.l)+': '+x.d+' días')+'"></i>';}).join('')+'</div>'+
      '<div class="mini">'+ok+' de 12 semanas cumplidas'+(mal.length?(' · de las que no, '+porG+' tenían 2+ guardias'):'')+'</div>';}
  return '';}
function objetivoNuevoCardHTML(o){
  /* los tipos nuevos: minutos por semana y agua al mes */
  let hoy=0,meta=+o.meta||1,sub='',lado='';
  if(o.tipo==='minutos'){hoy=minutosSemana(iso(mondayOf(new Date())));
    let t=0;for(let w=1;w<=8;w++)t+=minutosSemana(iso(addDays(mondayOf(new Date()),-7*w)));
    sub='min esta semana';lado='media 8 sem: '+Math.round(t/8)+'′';}
  else{const a=aguaMes(iso(new Date()).slice(0,7));hoy=a.m;sub='m este mes';lado='';}
  const pct=Math.min(100,Math.round(hoy/meta*100));
  return '<div class="card obj '+o.tipo+(hoy>=meta?' hecho':'')+'">'+
    '<div class="objcab"><b>'+esc(objetivoTitulo(o))+'</b><span class="e">'+(o.tipo==='minutos'?'TIEMPO':'AGUA')+'</span>'+
      '<button class="btn d s" data-a="obj-del" data-id="'+esc(o.id)+'" aria-label="quitar objetivo">×</button></div>'+
    '<div class="objnum"><b>'+hoy.toLocaleString('es-ES')+'</b><span>de '+meta.toLocaleString('es-ES')+' '+sub+'</span>'+(lado?('<i>'+esc(lado)+'</i>'):'')+'</div>'+
    '<div class="objbar"><i style="width:'+pct+'%"></i></div>'+
    (hoy<meta?'<div class="objvia"><span>faltan '+(meta-hoy).toLocaleString('es-ES')+(o.tipo==='minutos'?' min esta semana':' m este mes')+'</span></div>':'')+'</div>';}
/* ===================== SUPLEMENTOS: solo lo que tiene evidencia ===================== */
const SUP_PRESETS=[
  {p:'creatina',n:'Creatina monohidrato',d:'5 g',ev:'A',nota:'a diario, da igual la hora: funciona por acumulación'},
  {p:'cafeina',n:'Cafeína',d:'3 mg/kg',ev:'A',nota:'30–60 min antes de entrenar; nada en las 8 h antes de dormir'},
  {p:'proteina',n:'Proteína en polvo',d:'25–40 g',ev:'A',nota:'solo si con la comida no llegas a 1,6 g/kg'},
  {p:'vitd',n:'Vitamina D',d:'1 000–2 000 UI',ev:'B',nota:'solo si tu nivel está bajo'},
  {p:'betaalanina',n:'Beta-alanina',d:'3–6 g',ev:'B',nota:'esfuerzos de 1–4 min; el hormigueo es normal'},
  {p:'nitratos',n:'Nitratos (remolacha)',d:'≈ 8 mmol',ev:'B',nota:'2–3 h antes; sobre todo resistencia'},
  {p:'omega3',n:'Omega-3',d:'1–2 g EPA+DHA',ev:'C',nota:'poca evidencia en rendimiento'},
  {p:'magnesio',n:'Magnesio',d:'',ev:'C',nota:'solo si hay déficit'}];
function supsS(){const g=gymS();if(!Array.isArray(g.sups))g.sups=[];if(!g.supLog||typeof g.supLog!=='object'||Array.isArray(g.supLog))g.supLog={};return g.sups;}
function supPreset(s){return SUP_PRESETS.filter(function(x){return x.p===s.p;})[0]||null;}
function supTocaHoy(s,key){const d=parseDate(key);return !Array.isArray(s.dias)||!s.dias.length||(d&&s.dias.indexOf(d.getDay())>=0);}
function supTomado(id,key){const l=gymS().supLog[key];return Array.isArray(l)&&l.indexOf(id)>=0;}
function supToggle(id,key){supsS();const g=gymS(),l=Array.isArray(g.supLog[key])?g.supLog[key]:[];
  const i=l.indexOf(id);if(i>=0)l.splice(i,1);else l.push(id);
  if(l.length)g.supLog[key]=l;else delete g.supLog[key];save();}
function supAdherencia(id,lunKey){const l=parseDate(lunKey);let n=0,de=0;const s=supsS().filter(function(x){return x.id===id;})[0];
  for(let i=0;i<7;i++){const k=iso(addDays(l,i));if(k>iso(new Date()))break;if(s&&!supTocaHoy(s,k))continue;de++;if(supTomado(id,k))n++;}
  return {n:n,de:de};}
function cafeinaHoy(key){
  /* corte de cafeína: 8 h antes de tu hora de acostarte (vida media ≈ 5 h). Se cruza con la hora de entrenar */
  let bed=null;try{bed=mins(sleepOf(iso(addDays(parseDate(key),1))).bed);}catch(e){}
  if(bed==null)return null;
  const corte=bed-8*60,e=entrenoDe(key),hi=e&&e.hora?mins(e.hora):null;
  return {corte:hm(corte),bed:hm(bed),hi:hi!=null?hm(hi):'',vale:hi==null||hi-45<=corte};}
function supLineaTxt(s,key){
  const pr=supPreset(s),peso=+perfilS().pesoKg||0;
  if(s.p==='cafeina'){const c=cafeinaHoy(key);const mg=peso?(Math.round(peso*3/25)*25+' mg'):'3 mg/kg';
    if(!c)return mg+' · 30–60 min antes';
    return c.vale?(mg+' · vale hasta las '+c.corte+(c.hi?(' (entrenas '+c.hi+')'):'')):('hoy no: entrenas '+c.hi+' y a la cama '+c.bed+' → corte a las '+c.corte);}
  if(s.p==='proteina'){const t=foodTotals(key),obj=peso?Math.round(peso*1.6):0;
    return obj?(Math.round(t.prot||0)+' / '+obj+' g de proteína hoy (1,6 g/kg)'+((t.prot||0)>=obj?' · ya llegas':' · faltan '+(obj-Math.round(t.prot||0))+' g')):'pon tu peso en el perfil para calcularlo';}
  return (s.d||(pr&&pr.d)||'')+(pr&&pr.nota?(' · '+pr.nota):'');}
function renderGymSup(){
  const k=iso(new Date()),l=supsS(),lun=iso(mondayOf(new Date()));
  const ya={};l.forEach(function(s){ya[s.p]=1;});
  $('#main').innerHTML='<div class="grid">'+gymSubcab('Suplementos')+
    '<div class="card">'+(l.length?l.map(function(s){const pr=supPreset(s),on=supTomado(s.id,k),ad=supAdherencia(s.id,lun),es=s.p==='proteina';
      const caf=s.p==='cafeina'?cafeinaHoy(k):null;
      return '<div class="gsup"><button class="ck2'+(on?' on':'')+'" data-a="sup-tomar" data-id="'+esc(s.id)+'" data-k="'+k+'"'+(es?' disabled':'')+' aria-label="tomado hoy">'+(on?'✓':(es?'🥛':'·'))+'</button>'+
        '<div><b>'+esc(s.n)+(s.d?(' · '+esc(s.d)):'')+'</b><small'+(caf&&!caf.vale?' style="color:var(--warn)"':'')+'>'+esc(supLineaTxt(s,k))+(es?'':(' · '+ad.n+'/'+ad.de+' esta semana'))+'</small></div>'+
        '<span class="ev ev'+(pr?pr.ev:'C')+'">'+(pr?pr.ev:'?')+'</span><button class="gx" data-a="sup-del" data-id="'+esc(s.id)+'" aria-label="quitar">×</button></div>';}).join(''):
      '<div class="empty">Sin suplementos. Añade abajo solo lo que tomes: la app te lo recuerda en «Hoy» y lo cuenta en el informe.</div>')+'</div>'+
    '<div class="card"><b>Añadir</b><div class="gchips" style="flex-wrap:wrap">'+SUP_PRESETS.filter(function(x){return !ya[x.p];}).map(function(x){
      return '<button data-a="sup-add" data-p="'+x.p+'">'+esc(x.n)+' <b style="color:var(--'+(x.ev==='A'?'ok':(x.ev==='B'?'warn':'ink2'))+')">'+x.ev+'</b></button>';}).join('')+'</div>'+
      '<div class="row" style="margin-top:8px;gap:6px"><input id="supOtro" placeholder="otro: nombre y dosis" style="flex:1;min-width:0"><button class="btn s" data-a="sup-add" data-p="">añadir</button></div>'+
      '<p class="mini" style="margin:8px 0 0">A: evidencia fuerte en rendimiento (posicionamientos de la ISSN y el AIS). B: útil en casos concretos. C: poca evidencia. '+
      'Si tomas medicación o tienes una condición, confírmalo antes: esto es información general, no una pauta.</p></div></div>';}
/* ===================== INFORME DEL LUNES: la parte de entreno ===================== */
function guardiasSemana(lunKey){const l=parseDate(lunKey);let n=0;for(let i=0;i<7;i++){const sh=shiftById(dayInfo(iso(addDays(l,i))).shiftId);if(sh&&isGuardia(sh))n++;}return n;}
function informeEntrenoHTML(lk){
  const l=parseDate(lk),fin=iso(addDays(l,6)),g=gymS();
  const sem=[3,2,1,0].map(function(w){const lw=iso(addDays(l,-7*w));return {l:lw,c:cargaSemana(lw),g:guardiasSemana(lw)};});
  const mx=Math.max(1,sem.reduce(function(a,x){return Math.max(a,x.c);},0));
  const ac=acwrDe(fin);
  const ks={};for(let i=0;i<7;i++)ks[iso(addDays(l,i))]=1;
  const ses=g.sesiones.filter(function(s){return ks[s.fecha];});
  const reg=g.registro.filter(function(x){return ks[x.fecha]&&x.t!=='c';});
  const ton=Math.round(volDe(reg)/100)/10;
  const agua=reg.reduce(function(a,x){return a+(+x.m||0);},0)+g.cardio.filter(function(x){return ks[x.fecha]&&/nata|piscina/i.test(x.tipo||'');}).reduce(function(a,x){return a+Math.round((+x.distanciaKm||0)*1000);},0);
  const ll=eventosS().filter(function(e){return e.lloret&&ks[e.fecha];}).length;
  const sm=seriesMusculo(lk),regs=MREGIONES.filter(function(r){return sm[r]>0;});
  const bajos=['pecho','espalda','hombros','cuadriceps','isquiotibiales'].filter(function(r){return sm[r]<MUSC_OBJ.mev;}),altos=regs.filter(function(r){return sm[r]>MUSC_OBJ.mrv;});
  const sups=supsS().filter(function(s){return s.p!=='proteina';});
  /* la semana que viene */
  const sig=iso(addDays(l,7)),gSig=guardiasSemana(sig),rSig=entrenoSemana(sig);
  /* la siguiente rutina DE FUERZA: mandaba «+3 series de pecho · añadir a Piscina» */
  const sigRut=(function(){if(!rSig)return null;const x=rSig.dias.filter(function(d){const r=rSig.asig[d.k];return d.tipo==='fuerza'&&(d.base||d.auto||d.forz)&&r&&rutTipo(r)!=='agua';})[0];return x?rSig.asig[x.k]:null;})()||g.rutinas.filter(function(r){return rutTipo(r)!=='agua';})[0]||null;
  const recs=[];
  if(gSig>=3)recs.push('<b>Plan B:</b> '+gSig+' guardias. Dos días de fuerza de cuerpo entero y piscina en el saliente; no persigas el mínimo.');
  bajos.slice(0,2).forEach(function(r){const ej=MUSC_SUG[r],cap=ej.charAt(0).toUpperCase()+ej.slice(1),ya=sigRut&&sigRut.ejercicios.some(function(e){return normEj(e.ex)===normEj(cap);});
    recs.push('<b>+3 series de '+esc((MREG_LABEL[r]||r).toLowerCase())+'</b> ('+fmtKg(sm[r])+' esta semana): '+esc(ej)+'.'+(sigRut&&!ya?(' <button class="btn s" data-a="rt-add2" data-id="'+esc(sigRut.id)+'" data-n="'+esc(cap)+'">añadir a '+esc(sigRut.nombre)+'</button>'):''));});
  altos.forEach(function(r){recs.push('<b>−20 % de series de '+esc((MREG_LABEL[r]||r).toLowerCase())+'</b>: '+fmtKg(sm[r])+' pasa de lo que se recupera bien (~'+MUSC_OBJ.mrv+').');});
  if(ac&&ac.r>1.3)recs.push('<b>No subas más la carga</b>: esta semana fue '+String(ac.r).replace('.',',')+' veces tu media del mes. Repite volumen.');
  else if(ac&&ac.r<0.8)recs.push('<b>Puedes subir</b>: vas por debajo de tu media del mes ('+String(ac.r).replace('.',',')+').');
  if(bloqueDe(sig).descarga)recs.push('<b>Semana de descarga</b>: mitad de series y −10 %. La app ya lo aplica sola.');
  if(!recs.length)recs.push('Semana equilibrada: sigue igual.');
  const pos=ac?Math.max(0,Math.min(100,(ac.r-0.4)/1.4*100)):null;
  return '<div class="card infent"><h2>💪 Entreno</h2>'+
    '<div class="row"><b style="font-size:13px">Carga</b><span class="sp"></span><span class="mini">esfuerzo × minutos</span></div>'+
    '<div class="gbars" style="height:70px">'+sem.map(function(x,i){return '<div class="'+(x.g>=3?'gu':'')+'" style="height:'+Math.max(4,Math.round(x.c/mx*100))+'%'+(i===3?';background:var(--brand2);opacity:1':'')+'"><span>'+x.c+'</span></div>';}).join('')+'</div>'+
    '<div class="gbarsx">'+sem.map(function(x,i){return '<span>'+(i===3?'esta':('−'+(3-i)))+(x.g?(' · '+x.g+'G'):'')+'</span>';}).join('')+'</div>'+
    (ac?('<div class="gacwr"><i style="left:'+pos+'%"></i></div><div class="gacwrx"><span>poco</span><span>0,8–1,3 seguro</span><span>1,5 riesgo</span></div>'+
      '<p class="mini" style="margin:4px 0 0"><b style="color:var(--ink)">'+String(ac.r).replace('.',',')+'</b> esta semana frente a tu media del mes.</p>'):'<p class="mini">Con un mes de sesiones con esfuerzo apuntado sale si subes la carga demasiado rápido.</p>')+
    '<div class="ginfk"><div><b>'+ses.length+'</b><span>sesiones</span></div><div><b>'+reg.length+'</b><span>series</span></div><div><b>'+String(ton).replace('.',',')+' t</b><span>levantadas</span></div><div><b>'+(agua?(agua.toLocaleString('es-ES')+' m'):(ll?'🌊':'—'))+'</b><span>agua'+(ll?(' · '+ll+' Lloret'):'')+'</span></div></div>'+
    (regs.length?('<div class="ml">'+regs.sort(function(a,b){return sm[b]-sm[a];}).map(function(r){const n=sm[r],c=n>MUSC_OBJ.mrv?'hi':(n<MUSC_OBJ.mev?'lo':'ok');
      return '<span class="'+c+'">'+(c==='hi'?'▲ ':c==='lo'?'▼ ':'✓ ')+esc(MREG_LABEL[r]||r)+' '+fmtKg(n)+'</span>';}).join('')+'</div>'):'')+
    (sups.length?('<p class="mini" style="margin:8px 0 0">💊 '+sups.map(function(s){const a=supAdherencia(s.id,lk);return esc(s.n)+' '+a.n+'/'+a.de;}).join(' · ')+'</p>'):'')+
    '<div class="infrec"><b>La semana que viene'+(gSig?(' ('+gSig+' guardia'+(gSig===1?'':'s')+')'):'')+'</b>'+recs.map(function(r,i){return '<div class="rec"><span>'+(i+1)+'</span><div>'+r+'</div></div>';}).join('')+'</div>'+
  '</div>';}
/* ===================== CREAR UN PLAN DESDE TUS DÍAS REALES =====================
   No se empieza de cero: la app mira cuántos días de fuerza te caben de media con tu rotación en
   las próximas 8 semanas y te enseña qué plantillas encajan y cuáles no. Las series, el rango de
   reps y el descanso salen del objetivo; los ejercicios, del material que tengas. */
function capacidadSemanas(n){
  const lun=mondayOf(new Date());let fz=0,pis=0,g3=0;
  for(let w=0;w<n;w++){const s=entrenoSemana(iso(addDays(lun,7*w)));if(!s)continue;
    /* los días en que cabe fuerza (sin guardia, saliente ni evento a esa hora) menos uno de
       descanso: con 6 guardias al mes y el Lloretazo cada noche no caben 6 de media */
    fz+=Math.max(0,s.dias.filter(function(x){return x.tipo==='fuerza'&&!x.choca&&!x.quitado;}).length-1);
    pis+=s.dias.filter(function(x){return x.tipo==='pisc';}).length;
    if(s.guardias>=3)g3++;}
  return {fuerza:Math.round(fz/n*10)/10,pisc:Math.round(pis/n*10)/10,semanas3g:g3,n:n};}
