  const m=/(\d+)\s*(p[aá]ginas?|p[aá]gs?|min(?:utos)?|vasos?|km|flexiones|sentadillas|veces|series|posturas|ejercicios|palabras|preguntas|tarjetas)\b/i.exec(n||'');
